// Cloudflare Worker for FinPress
const HTML = "<!DOCTYPE html>\n<html lang=\"en\" class=\"h-full antialiased\" data-theme=\"light\">\n<head>\n  <meta charset=\"utf-8\"/>\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=5, viewport-fit=cover\"/>\n  <title>FinPress Institutional Workspace \u2014 Trader Terminal</title>\n  <script src=\"https://www.gstatic.com/antigravity/web/dev/tailwindcss.min.js\"></script>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,100..1000;1,9..40,100..1000&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n  <script>\n    tailwind.config = {\n      darkMode: 'class',\n      theme: {\n        extend: {\n          fontFamily: {\n            sans: ['\"DM Sans\"', '\"Plus Jakarta Sans\"', 'system-ui', '-apple-system', 'BlinkMacSystemFont', 'sans-serif'],\n            mono: ['\"JetBrains Mono\"', 'monospace'],\n          },\n          colors: {\n            brand: { 50: '#EEF2FF', 100: '#E0E7FF', 500: '#6366F1', 600: '#4F46E5', 700: '#4338CA' }\n          }\n        }\n      }\n    }\n  </script>\n  <style>\n    html, body {\n      touch-action: manipulation;\n      -webkit-text-size-adjust: 100%;\n    }\n    body { font-family: 'DM Sans', 'Plus Jakarta Sans', system-ui, -apple-system, BlinkMacSystemFont, sans-serif; font-size: 14px; font-weight: 400; color: #090D16; font-size: 13.5px; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; text-rendering: optimizeLegibility; }\n    .font-mono { font-family: 'JetBrains Mono', monospace; }\n    ::-webkit-scrollbar { width: 5px; height: 5px; }\n    ::-webkit-scrollbar-track { background: transparent; }\n    ::-webkit-scrollbar-thumb { background: #CBD5E1; border-radius: 4px; }\n    .dark ::-webkit-scrollbar-thumb { background: #334155; }\n    .table-row-hover:hover { background-color: rgba(99, 102, 241, 0.05); }\n    .dark .table-row-hover:hover { background-color: rgba(99, 102, 241, 0.10); }\n    mark { background-color: #FEF08A; color: #854D0E; padding: 0 2px; border-radius: 2px; font-weight: 700; }\n    .dark mark { background-color: #854D0E; color: #FEF08A; }\n    @supports (padding: max(0px)) {\n      body {\n        padding-left: env(safe-area-inset-left);\n        padding-right: env(safe-area-inset-right);\n        padding-bottom: env(safe-area-inset-bottom);\n      }\n    }\n  </style>\n</head>\n<body class=\"min-h-full bg-[#F1F5F9] text-slate-900 dark:bg-[#070B14] dark:text-slate-100 transition-colors duration-150\">\n  <div class=\"min-h-screen flex flex-col\">\n\n    <!-- ================= 1. UNIFIED TOP NAVIGATION & CONTROLS RIBBON (NEWSPAPER BROADSHEET) ================= -->\n    <header class=\"sticky top-0 z-50 bg-[#FBE8D8] dark:bg-[#0E1320] border-b-2 border-[#DFC0A5] dark:border-slate-800 text-[#1C1917] dark:text-slate-100 shadow-sm px-3 py-1.5 flex items-center justify-between gap-3 overflow-x-auto whitespace-nowrap text-[12px] font-mono\">\n      \n      <!-- Left: FinPress Branding & Live Market Pulse -->\n      <div class=\"flex items-center gap-3 shrink-0\">\n        <div class=\"flex items-center gap-1.5 shrink-0 cursor-pointer\" onclick=\"onCategorySelect('ALL')\" title=\"Reset to All News\">\n          <div class=\"w-6.5 h-6.5 rounded bg-[#1C1917] dark:bg-amber-600 flex items-center justify-center shadow-xs border border-amber-900/40\">\n            <span class=\"text-[#FDF2E9] text-[11px] font-bold tracking-tight font-mono\">FP</span>\n          </div>\n          <span class=\"text-[15px] font-bold tracking-tight text-[#1C1917] dark:text-white mr-1 font-mono\">\n            Fin<span class=\"text-amber-800 dark:text-amber-400\">Press</span>\n          </span>\n        </div>\n\n        <!-- Live Market Pulse Key Data in Newspaper Broadsheet Tone -->\n        <div class=\"flex items-center gap-3 text-[11.5px] border-l border-[#D5B599] dark:border-slate-800 pl-3\">\n          <span class=\"text-[#3D2817] dark:text-slate-300 font-medium\">NIFTY <b class=\"text-emerald-700 dark:text-emerald-400 font-bold font-mono\">24,835 (+0.64%)</b></span>\n          <span class=\"text-[#3D2817] dark:text-slate-300 font-medium\">BANK NIFTY <b class=\"text-emerald-700 dark:text-emerald-400 font-bold font-mono\">54,120 (+0.82%)</b></span>\n          <span class=\"text-[#3D2817] dark:text-slate-300 font-medium\">INDIA VIX <b class=\"text-rose-700 dark:text-rose-400 font-bold font-mono\">12.85 (-3.2%)</b></span>\n          <span class=\"text-[#3D2817] dark:text-slate-300 font-medium\">BRENT <b class=\"text-amber-800 dark:text-amber-300 font-bold font-mono\">$74.2/bbl</b></span>\n          <span class=\"text-[#3D2817] dark:text-slate-300 font-medium\">USD/INR <b class=\"text-[#1C1917] dark:text-slate-100 font-bold font-mono\">\u20b983.65</b></span>\n        </div>\n      </div>\n\n      <!-- Right: Hide/Unhide 3rd Col + Search + Calendar + Status + Total + Font + Theme -->\n      <div class=\"flex items-center gap-2 shrink-0\">\n        \n        <div class=\"relative w-36 sm:w-44\">\n          <input type=\"text\" id=\"global-search\" oninput=\"onSearchInput()\" placeholder=\"Search stock or news...\" class=\"w-full text-[11.5px] pl-6 pr-5 py-1 rounded-md border border-[#D5B599] dark:border-slate-700 bg-white/90 dark:bg-slate-900 text-[#1C1917] dark:text-slate-100 placeholder-[#8C6D58] dark:placeholder-slate-400 focus:outline-none focus:border-amber-700 font-mono shadow-2xs\"/>\n          <span class=\"absolute left-1.5 top-1.5 text-slate-500 text-[10.5px]\">\ud83d\udd0d</span>\n          <button id=\"clear-search-btn\" onclick=\"clearSearch()\" class=\"hidden absolute right-1.5 top-1 text-slate-500 hover:text-black dark:hover:text-white text-[11px] font-bold p-0.5\">\u2715</button>\n        </div>\n\n        <!-- Historical Calendar & Edition Navigation -->\n        <div class=\"flex items-center gap-0.5 bg-white/80 dark:bg-slate-900 p-0.5 rounded-md border border-[#D5B599] dark:border-slate-700/80 font-mono text-[11.5px]\">\n          <button onclick=\"navigateDate(-1)\" class=\"px-1.5 py-0.5 rounded hover:bg-black/10 dark:hover:bg-slate-800 text-[#1C1917] dark:text-slate-300 font-bold\" title=\"Previous Date (\u25c0)\">\u25c0</button>\n          <div class=\"flex items-center gap-1 px-1 py-0.5 bg-[#FBE8D8]/90 dark:bg-black/60 rounded border border-[#DFC0A5] dark:border-slate-800\">\n            <span class=\"text-slate-600 dark:text-slate-400 text-[10.5px]\">\ud83d\udcc5</span>\n            <input type=\"date\" id=\"calendar-picker\" onchange=\"onCalendarSelect(this.value)\" class=\"bg-transparent text-[#1C1917] dark:text-slate-100 font-bold font-mono text-[11.5px] focus:outline-none cursor-pointer [color-scheme:light] dark:[color-scheme:dark] max-w-[105px]\"/>\n          </div>\n          <button onclick=\"navigateDate(1)\" class=\"px-1.5 py-0.5 rounded hover:bg-black/10 dark:hover:bg-slate-800 text-[#1C1917] dark:text-slate-300 font-bold\" title=\"Next Date (\u25b6)\">\u25b6</button>\n        </div>\n\n        <div id=\"source-health-container\" class=\"flex items-center gap-1 font-mono text-[10.5px]\"></div>\n\n        <span id=\"total-news-counter-badge\" class=\"px-2 py-0.5 rounded bg-emerald-600/15 border border-emerald-600/30 text-emerald-900 dark:text-emerald-400 font-extrabold font-mono text-[11.5px]\">\n          \ud83d\udd25 <b id=\"top-total-count\">0</b>\n        </span>\n\n        <!-- Font Size Controls -->\n        <div class=\"flex items-center bg-white/80 dark:bg-slate-900 p-0.5 rounded-md border border-[#D5B599] dark:border-slate-700 text-[11px] font-mono font-semibold\">\n          <button onclick=\"adjustFontSize(-1)\" class=\"px-1.5 py-0.5 rounded text-[#1C1917] dark:text-slate-300 hover:bg-black/10 dark:hover:bg-slate-800\" title=\"Decrease Font Size (A-)\">A-</button>\n          <span id=\"font-size-label\" class=\"px-1 text-[9.5px] text-slate-700 dark:text-slate-400 select-none\">100%</span>\n          <button onclick=\"adjustFontSize(1)\" class=\"px-1.5 py-0.5 rounded text-[#1C1917] dark:text-slate-300 hover:bg-black/10 dark:hover:bg-slate-800\" title=\"Increase Font Size (A+)\">A+</button>\n        </div>\n\n        <button onclick=\"toggleTheme()\" class=\"w-6.5 h-6.5 rounded-md border border-[#D5B599] dark:border-slate-700 bg-white/80 dark:bg-slate-900 text-[#1C1917] dark:text-slate-300 hover:bg-white dark:hover:text-white flex items-center justify-center text-[11px] shadow-xs\" title=\"Toggle Light/Dark Theme\">\n          <span id=\"theme-icon\">\ud83c\udf19</span>\n        </button>\n      </div>\n\n    </header>\n\n    <!-- ================= MAIN THREE-COLUMN WORKSPACE (FULL-WIDTH 3-COLUMN LAYOUT) ================= -->\n    <main class=\"w-full px-2 sm:px-3 py-1.5 flex-1 flex flex-col gap-1.5\">\n      \n      <!-- Diagnostic Source Health Alert Banner (Appears when any paper fails) -->\n      <div id=\"source-alert-banner\" class=\"hidden px-3 py-1.5 rounded-lg bg-amber-500/15 border border-amber-500/40 text-amber-900 dark:text-amber-200 text-[11px] font-mono flex items-center justify-between gap-2 shadow-2xs\">\n        <div class=\"flex items-center gap-2\">\n          <span class=\"text-sm\">\u26a0\ufe0f</span>\n          <span id=\"source-alert-text\">Business Standard session failed to authenticate.</span>\n        </div>\n        <button onclick=\"document.getElementById('source-alert-banner').classList.add('hidden')\" class=\"text-slate-400 hover:text-white text-xs font-bold px-1.5 py-0.5\" title=\"Dismiss\">\u2715</button>\n      </div>\n\n      <!-- IPO Central Sub-tabs Header Banner (Appears when IPO Central Desk is active) -->\n      <div id=\"ipo-subtabs-banner\" class=\"hidden rounded-xl bg-white dark:bg-[#0E1322] border border-amber-300/80 dark:border-amber-900/60 p-2 shadow-2xs items-center justify-between gap-2 flex-wrap\">\n        <div class=\"flex items-center gap-2\">\n          <span class=\"text-[12.5px] font-bold font-mono text-amber-950 dark:text-amber-300 flex items-center gap-1.5 px-2\">\n            <span>\ud83d\ude80</span> <span>Primary Market & IPO Intelligence Desk</span>\n          </span>\n          <div class=\"flex items-center bg-slate-100 dark:bg-[#141C33] p-1 rounded-lg border border-slate-200 dark:border-slate-800 text-[12px] font-bold\">\n            <button id=\"ipo-tab-all\" onclick=\"selectIpoSub('ALL')\" class=\"px-3 py-1 rounded-md bg-[#1C1917] text-[#FFF8F0] dark:bg-indigo-600 dark:text-white shadow-xs transition-all flex items-center gap-1.5 font-semibold\">\n              <span>\u2728 All IPOs</span>\n              <span id=\"ipo-sub-all-count\" class=\"px-1.5 py-0.2 rounded text-[10px] bg-white/20 dark:bg-black/30 font-mono\">0</span>\n            </button>\n            <button id=\"ipo-tab-drhp\" onclick=\"selectIpoSub('DRHP')\" class=\"px-3 py-1 rounded-md text-slate-800 dark:text-slate-300 hover:text-black dark:hover:text-white hover:bg-white/60 dark:hover:bg-slate-800 transition-all flex items-center gap-1.5 font-medium\">\n              <span>\ud83d\udccb DRHP</span>\n              <span id=\"ipo-sub-drhp-count\" class=\"px-1.5 py-0.2 rounded text-[10px] bg-slate-200 dark:bg-slate-700 font-mono\">0</span>\n            </button>\n            <button id=\"ipo-tab-bidding\" onclick=\"selectIpoSub('BIDDING')\" class=\"px-3 py-1 rounded-md text-slate-800 dark:text-slate-300 hover:text-black dark:hover:text-white hover:bg-white/60 dark:hover:bg-slate-800 transition-all flex items-center gap-1.5 font-medium\">\n              <span>\ud83d\udcc8 Bidding</span>\n              <span id=\"ipo-sub-bidding-count\" class=\"px-1.5 py-0.2 rounded text-[10px] bg-slate-200 dark:bg-slate-700 font-mono\">0</span>\n            </button>\n            <button id=\"ipo-tab-notices\" onclick=\"selectIpoSub('NOTICES')\" class=\"px-3 py-1 rounded-md text-slate-800 dark:text-slate-300 hover:text-black dark:hover:text-white hover:bg-white/60 dark:hover:bg-slate-800 transition-all flex items-center gap-1.5 font-medium\">\n              <span>\ud83c\udfdb\ufe0f Allotments</span>\n              <span id=\"ipo-sub-notices-count\" class=\"px-1.5 py-0.2 rounded text-[10px] bg-slate-200 dark:bg-slate-700 font-mono\">0</span>\n            </button>\n          </div>\n        </div>\n        <span class=\"text-[11.5px] font-mono text-slate-500 dark:text-slate-400 font-bold px-2\">\n          DRHP filings, live subscription demand & basis of allotment\n        </span>\n      </div>\n\n      <!-- Corporate Sub-tabs Header Banner (Appears when Corporate Desk is active) -->\n      <div id=\"corporate-subtabs-banner\" class=\"hidden rounded-xl bg-white dark:bg-[#0E1322] border border-indigo-200/90 dark:border-indigo-900/60 p-2 shadow-2xs items-center justify-between gap-2 flex-wrap\">\n        <div class=\"flex items-center gap-2\">\n          <span class=\"text-[12.5px] font-bold font-mono text-indigo-950 dark:text-indigo-300 flex items-center gap-1.5 px-2\">\n            <span>\ud83c\udfe2</span> <span>Corporate Intelligence Desk</span>\n          </span>\n          <div class=\"flex items-center bg-slate-100 dark:bg-[#141C33] p-1 rounded-lg border border-slate-200 dark:border-slate-800 text-[12px] font-bold\">\n            <button id=\"corp-tab-all\" onclick=\"selectCorporateSub('ALL')\" class=\"px-3 py-1 rounded-md bg-[#1C1917] text-[#FFF8F0] dark:bg-indigo-600 dark:text-white shadow-xs transition-all flex items-center gap-1.5 font-semibold\">\n              <span>\ud83c\udfe2 All Corporate</span>\n              <span id=\"corp-sub-all-count\" class=\"px-1.5 py-0.2 rounded text-[10px] bg-white/20 dark:bg-black/30 font-mono\">0</span>\n            </button>\n            <button id=\"corp-tab-events\" onclick=\"selectCorporateSub('EVENTS')\" class=\"px-3 py-1 rounded-md text-slate-800 dark:text-slate-300 hover:text-black dark:hover:text-white hover:bg-white/60 dark:hover:bg-slate-800 transition-all flex items-center gap-1.5 font-medium\">\n              <span>\ud83d\udce2 Events</span>\n              <span id=\"corp-sub-events-count\" class=\"px-1.5 py-0.2 rounded text-[10px] bg-slate-200 dark:bg-slate-700 font-mono\">0</span>\n            </button>\n            <button id=\"corp-tab-appts\" onclick=\"selectCorporateSub('APPOINTMENTS')\" class=\"px-3 py-1 rounded-md text-slate-800 dark:text-slate-300 hover:text-black dark:hover:text-white hover:bg-white/60 dark:hover:bg-slate-800 transition-all flex items-center gap-1.5 font-medium\">\n              <span>\ud83d\udc54 Appointments</span>\n              <span id=\"corp-sub-appts-count\" class=\"px-1.5 py-0.2 rounded text-[10px] bg-slate-200 dark:bg-slate-700 font-mono\">0</span>\n            </button>\n          </div>\n        </div>\n        <span class=\"text-[11.5px] font-mono text-slate-500 dark:text-slate-400 font-bold px-2\">\n          Disclosures, statutory filings & management appointments\n        </span>\n      </div>\n\n      <!-- ================= VIEW 1: NEWS STREAM (3-COLUMN SIDE-BY-SIDE EXPANDED LAYOUT) ================= -->\n      <section id=\"view-feed\" class=\"grid grid-cols-1 lg:grid-cols-[285px_minmax(0,1fr)_240px] xl:grid-cols-[305px_minmax(0,1fr)_255px] 2xl:grid-cols-[320px_minmax(0,1fr)_270px] gap-2.5 items-start\">\n        \n        <!-- COLUMN 1: HIGH-DENSITY TERMINAL NEWS WIRE (1-LINER STORIES, MAX 10 PER PAGE) -->\n        <div class=\"rounded-lg bg-white dark:bg-[#0E1322] border border-slate-200 dark:border-slate-800 overflow-hidden shadow-xs flex flex-col\">\n          <div class=\"px-2.5 py-1.5 border-b border-slate-200 dark:border-slate-800 bg-slate-100/90 dark:bg-slate-900/80 flex items-center justify-between text-[11px] font-mono\">\n            <span id=\"feed-list-count\" class=\"font-extrabold text-slate-900 dark:text-slate-100\">0 Stories</span>\n            <div class=\"flex items-center gap-1\">\n              <button onclick=\"navigateStory(-1)\" class=\"px-1.5 py-0.2 rounded bg-white dark:bg-slate-800 hover:bg-indigo-50 text-[10px] font-bold text-slate-900 dark:text-slate-200 border border-slate-300 dark:border-slate-700\" title=\"Previous Story (K or Up Arrow)\">\u25b2 Prev</button>\n              <button onclick=\"navigateStory(1)\" class=\"px-1.5 py-0.2 rounded bg-white dark:bg-slate-800 hover:bg-indigo-50 text-[10px] font-bold text-slate-900 dark:text-slate-200 border border-slate-300 dark:border-slate-700\" title=\"Next Story (J or Down Arrow)\">\u25bc Next</button>\n            </div>\n          </div>\n\n          <div id=\"feed-list-container\" class=\"divide-y divide-slate-100 dark:divide-slate-800/80 flex flex-col\">\n            <!-- Dynamically populated 1-liner story items (Max 10) -->\n          </div>\n\n          <!-- COLUMN 1 PAGINATION BAR (10 STORIES PER PAGE) -->\n          <div id=\"feed-pagination\" class=\"px-2.5 py-1.5 border-t border-slate-200 dark:border-slate-800 bg-slate-50/90 dark:bg-slate-900/80 flex items-center justify-between text-[11px] font-mono\">\n            <span id=\"feed-pagination-info\" class=\"font-bold text-slate-700 dark:text-slate-300\">Page 1 / 1</span>\n            <div class=\"flex items-center gap-1\">\n              <button id=\"feed-prev-page\" onclick=\"changeFeedPage(-1)\" class=\"px-2 py-0.5 rounded bg-white dark:bg-slate-800 hover:bg-indigo-50 text-[10.5px] font-bold text-slate-900 dark:text-slate-200 border border-slate-300 dark:border-slate-700 shadow-2xs\">\u25c0 Prev</button>\n              <button id=\"feed-next-page\" onclick=\"changeFeedPage(1)\" class=\"px-2 py-0.5 rounded bg-white dark:bg-slate-800 hover:bg-indigo-50 text-[10.5px] font-bold text-slate-900 dark:text-slate-200 border border-slate-300 dark:border-slate-700 shadow-2xs\">Next \u25b6</button>\n            </div>\n          </div>\n        </div>\n\n        <!-- COLUMN 2: ACTIVE STORY DEEP DIVE & CATALYST INTELLIGENCE (WIDE READING PANE) -->\n        <div id=\"feed-detail-wrapper\" class=\"rounded-lg bg-white dark:bg-[#0E1322] border border-slate-200 dark:border-slate-800 p-3 sm:p-4 shadow-xs lg:sticky lg:top-[44px] flex flex-col gap-2.5 lg:min-h-[calc(100vh-5.5rem)] lg:max-h-[calc(100vh-5.5rem)] lg:overflow-y-auto\">\n          <div id=\"feed-detail-container\">\n            <!-- Dynamically populated active story intelligence -->\n          </div>\n        </div>\n\n        <!-- COLUMN 3: RIGHT HAND SIDE PANEL (TREE VIEW: CATEGORIES [OPEN], SECTORS & STOCKS [COLLAPSED]) -->\n        <!-- COLUMN 3: RIGHT HAND SIDE PANEL (COLLAPSIBLE VERTICAL PILL & ACCORDION DRAWER) -->\n        <div class=\"flex items-start gap-1 lg:sticky lg:top-[44px] lg:max-h-[calc(100vh-3.5rem)]\">\n          \n          <!-- A. Vertical Pill when Collapsed (Matching Image 1) -->\n          <button id=\"sidebar-vertical-pill\" onclick=\"toggleSidebar()\" class=\"hidden flex-col items-center gap-2 py-4 px-1.5 rounded-full border border-slate-300 dark:border-slate-700 bg-white dark:bg-[#0E1322] text-[#090D16] dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800 shadow-sm cursor-pointer select-none transition-all shrink-0 w-8\" title=\"Expand Categories, Sectors & Stocks\">\n            <span class=\"text-xs font-bold text-slate-700 dark:text-slate-300\">\u2630</span>\n            <span class=\"font-sans text-[10px] font-medium tracking-wider uppercase [writing-mode:vertical-lr] rotate-180 text-slate-700 dark:text-slate-300 py-1\">\n              CATEGORIES & DESKS\n            </span>\n          </button>\n\n          <!-- B. Full Drawer when Open (Matching Image 2) -->\n          <aside id=\"view-feed-aside\" class=\"flex flex-col rounded-xl bg-white dark:bg-[#0E1322] border border-slate-200 dark:border-slate-800 shadow-xs overflow-hidden w-full min-w-[240px] max-w-[280px] lg:max-h-[calc(100vh-3.5rem)] lg:overflow-y-auto transition-all\">\n            \n            <!-- Header (Matching Image 2: Title, Count, Collapse Chevron < ) -->\n            <div class=\"flex items-center justify-between px-3 py-2.5 bg-white dark:bg-[#0E1322] border-b border-slate-100 dark:border-slate-800\">\n              <span class=\"text-[11.5px] font-sans font-bold uppercase tracking-wider text-slate-900 dark:text-slate-100\">\n                CATEGORIES & DESKS\n              </span>\n              <div class=\"flex items-center gap-2 text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n                <span id=\"sidebar-total-stat\">14 \u00b7 Total</span>\n                <button onclick=\"toggleSidebar()\" class=\"w-6 h-6 rounded flex items-center justify-center hover:bg-slate-100 dark:hover:bg-slate-800 text-slate-500 hover:text-black dark:hover:text-white font-bold cursor-pointer text-base leading-none transition-colors\" title=\"Collapse to Pill (\u2039)\">\n                  \u2039\n                </button>\n              </div>\n            </div>\n\n            <!-- Search Input Box (Matching Image 2) -->\n            <div class=\"p-2 border-b border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/40\">\n              <div class=\"relative\">\n                <input type=\"text\" id=\"sidebar-filter-input\" oninput=\"onSidebarFilterInput(this.value)\" placeholder=\"Search category or stock...\" class=\"w-full text-[12px] pl-6 pr-2 py-1 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-[#0E1322] text-[#090D16] dark:text-slate-100 placeholder-slate-400 focus:outline-none focus:border-indigo-500 font-sans\"/>\n                <span class=\"absolute left-2 top-1.5 text-slate-400 text-[10.5px]\">\ud83d\udd0d</span>\n              </div>\n            </div>\n\n            <!-- Expand / Collapse All Toggle (Matching Image 2) -->\n            <div class=\"flex items-center justify-between px-3 py-1.5 bg-white dark:bg-[#0E1322] text-[11px] font-sans border-b border-slate-100 dark:border-slate-800\">\n              <span id=\"active-filter-indicator\" class=\"text-amber-700 dark:text-amber-400 font-medium text-[10.5px]\"></span>\n              <button onclick=\"toggleAllTreeSections()\" id=\"expand-collapse-all-btn\" class=\"text-slate-600 dark:text-slate-400 hover:text-black dark:hover:text-white font-medium flex items-center gap-1 cursor-pointer\">\n                <span>\u229e</span> <span id=\"expand-all-text\">Expand all</span>\n              </button>\n            </div>\n\n            <!-- Dynamic Accordion Rows (Matching Image 2) -->\n            <div id=\"sidebar-accordion-container\" class=\"divide-y divide-slate-100 dark:divide-slate-800/80 flex flex-col font-sans\">\n              <!-- Dynamically populated accordion items with left blue border for active -->\n            </div>\n\n          </aside>\n\n        </div>\n\n      </section>\n\n      <!-- ================= VIEW 2: TABULAR IPO CENTRAL ================= -->\n      <section id=\"view-ipo\" class=\"hidden flex-col gap-2\">\n        <div class=\"rounded-xl bg-white dark:bg-[#0E1322] border border-slate-200 dark:border-slate-800 shadow-xs overflow-hidden flex flex-col\">\n          \n          <div class=\"px-4 py-2.5 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between bg-slate-50/90 dark:bg-[#11172A]/90 text-[12.5px] font-mono flex-wrap gap-2\">\n            <div class=\"flex items-center gap-2\">\n              <span class=\"font-bold text-slate-900 dark:text-slate-100 flex items-center gap-1.5 mr-2\">\n                <span>\ud83d\ude80</span> <span>PRIMARY MARKET TRACKER</span>\n              </span>\n              <div class=\"flex items-center bg-slate-200/80 dark:bg-[#151D33] p-0.5 rounded-lg border border-slate-300/80 dark:border-slate-700 text-[11.5px] font-bold\">\n                <button id=\"ipo-tab-all\" onclick=\"filterIpoTable('ALL')\" class=\"px-2.5 py-1 rounded-md bg-indigo-600 text-white shadow-xs transition-all flex items-center gap-1.5 font-bold\">\n                  <span>\u2728 All IPOs</span>\n                  <span id=\"ipo-sub-all-count\" class=\"px-1.5 py-0.2 rounded text-[10px] bg-black/30 font-mono\">0</span>\n                </button>\n                <button id=\"ipo-tab-drhp\" onclick=\"filterIpoTable('DRHP')\" class=\"px-2.5 py-1 rounded-md text-slate-700 dark:text-slate-300 hover:text-white hover:bg-slate-800 transition-all flex items-center gap-1.5 font-medium\">\n                  <span>\ud83d\udccb DRHP</span>\n                  <span id=\"ipo-sub-drhp-count\" class=\"px-1.5 py-0.2 rounded text-[10px] bg-slate-100 dark:bg-slate-700 font-mono\">0</span>\n                </button>\n                <button id=\"ipo-tab-bidding\" onclick=\"filterIpoTable('BIDDING')\" class=\"px-2.5 py-1 rounded-md text-slate-700 dark:text-slate-300 hover:text-white hover:bg-slate-800 transition-all flex items-center gap-1.5 font-medium\">\n                  <span>\ud83d\udcc8 Bidding</span>\n                  <span id=\"ipo-sub-bidding-count\" class=\"px-1.5 py-0.2 rounded text-[10px] bg-slate-100 dark:bg-slate-700 font-mono\">0</span>\n                </button>\n                <button id=\"ipo-tab-notices\" onclick=\"filterIpoTable('NOTICES')\" class=\"px-2.5 py-1 rounded-md text-slate-700 dark:text-slate-300 hover:text-white hover:bg-slate-800 transition-all flex items-center gap-1.5 font-medium\">\n                  <span>\ud83c\udfdb\ufe0f Allotments</span>\n                  <span id=\"ipo-sub-notices-count\" class=\"px-1.5 py-0.2 rounded text-[10px] bg-slate-100 dark:bg-slate-700 font-mono\">0</span>\n                </button>\n              </div>\n            </div>\n            <span class=\"text-slate-500 dark:text-slate-400 font-bold text-[12px]\">Total Tracked: <b id=\"ipo-table-visible-count\" class=\"text-brand-600 dark:text-indigo-400\">0</b> Records</span>\n          </div>\n\n          <div class=\"overflow-x-auto max-h-[calc(100vh-7.5rem)] overflow-y-auto\">\n            <table class=\"w-full text-left border-collapse text-[13.5px]\">\n              <thead class=\"sticky top-0 z-10 bg-slate-100 dark:bg-[#141A2E] shadow-xs\">\n                <tr class=\"border-b border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-400 text-[11.5px] font-mono uppercase tracking-wider font-bold\">\n                  <th class=\"py-2.5 px-3.5\">#</th>\n                  <th class=\"py-2.5 px-3.5 min-w-[240px]\">Company / Issuer & Exchange</th>\n                  <th class=\"py-2.5 px-3.5 min-w-[120px]\">Issue Size</th>\n                  <th class=\"py-2.5 px-3.5 min-w-[140px]\">Stage / Status</th>\n                  <th class=\"py-2.5 px-3.5 min-w-[130px]\">Subscription Demand</th>\n                  <th class=\"py-2.5 px-3.5 min-w-[360px]\">Key Analyst Insight & Breakdown</th>\n                  <th class=\"py-2.5 px-3.5 min-w-[130px]\">Source</th>\n                  <th class=\"py-2.5 px-3.5 text-center\">Full Info</th>\n                </tr>\n              </thead>\n              <tbody id=\"ipo-table-body\" class=\"divide-y divide-slate-100 dark:divide-slate-800/70\">\n                <!-- Dynamically populated IPO rows -->\n              </tbody>\n            </table>\n          </div>\n\n        </div>\n      </section>\n\n      <!-- ================= VIEW 3: TABULAR MASTER NEWS MATRIX (INSTITUTIONAL TABLE) ================= -->\n      <section id=\"view-matrix\" class=\"hidden flex-col gap-2\">\n        <div class=\"rounded-xl bg-white dark:bg-[#0E1322] border border-slate-200 dark:border-slate-800 shadow-xs overflow-hidden flex flex-col\">\n          \n          <div class=\"px-4 py-2.5 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between bg-slate-50/70 dark:bg-[#11172A]/70 text-[12.5px] font-mono\">\n            <span class=\"font-bold text-slate-800 dark:text-slate-200 flex items-center gap-2\">\n              <span>\ud83d\udcca</span> <span>MASTER FINANCIAL NEWS MATRIX (Full Unabridged Intelligence Stream)</span>\n            </span>\n            <span class=\"text-slate-400\">Total Displayed: <b id=\"matrix-table-visible-count\" class=\"text-brand-600 font-bold\">0</b> Stories</span>\n          </div>\n\n          <div class=\"overflow-x-auto max-h-[calc(100vh-7.5rem)] overflow-y-auto\">\n            <table class=\"w-full text-left border-collapse text-[13.5px]\">\n              <thead class=\"sticky top-0 z-10 bg-slate-100 dark:bg-[#141A2E] shadow-xs\">\n                <tr class=\"border-b border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-400 text-[11px] font-mono uppercase tracking-wider font-bold\">\n                  <th class=\"py-2.5 px-3\">#</th>\n                  <th class=\"py-2.5 px-3.5 min-w-[280px]\">Headline & Core Development</th>\n                  <th class=\"py-2.5 px-3 min-w-[110px]\">Section</th>\n                  <th class=\"py-2.5 px-3 min-w-[100px]\">Sentiment</th>\n                  <th class=\"py-2.5 px-3 min-w-[120px]\">Page / Source</th>\n                  <th class=\"py-2.5 px-3 min-w-[130px]\">Tickers</th>\n                  <th class=\"py-2.5 px-3.5 min-w-[360px]\">Executive Intelligence Summary</th>\n                  <th class=\"py-2.5 px-3 text-center\">Full Info</th>\n                </tr>\n              </thead>\n              <tbody id=\"matrix-table-body\" class=\"divide-y divide-slate-100 dark:divide-slate-800/70\">\n                <!-- Dynamically populated Matrix rows -->\n              </tbody>\n            </table>\n          </div>\n\n        </div>\n      </section>\n\n    </main>\n\n  </div>\n\n  <!-- ================= STORY FULL DETAILS MODAL ================= -->\n  <div id=\"story-modal\" class=\"fixed inset-0 z-50 bg-black/60 backdrop-blur-xs hidden items-center justify-center p-4\">\n    <div class=\"bg-white dark:bg-[#0E1322] border border-slate-200 dark:border-slate-800 rounded-2xl max-w-3xl w-full p-6 shadow-2xl flex flex-col gap-4 max-h-[90vh] overflow-y-auto\">\n      <div class=\"flex items-start justify-between border-b border-slate-100 dark:border-slate-800 pb-3\">\n        <div>\n          <div class=\"flex items-center gap-2\">\n            <span id=\"story-modal-category\" class=\"px-2 py-0.5 rounded text-[10.5px] font-mono font-bold bg-slate-100 text-slate-800 dark:bg-slate-800 dark:text-slate-200\">Policy</span>\n            <span id=\"story-modal-sentiment\" class=\"px-2 py-0.5 rounded text-[10.5px] font-mono font-bold bg-emerald-50 text-emerald-800 border border-emerald-200\">\ud83d\udfe2 BULLISH</span>\n            <span id=\"story-modal-pages\" class=\"text-xs font-mono text-slate-500\">FE (Page 1)</span>\n          </div>\n          <h2 id=\"story-modal-headline\" class=\"text-xl font-extrabold text-slate-900 dark:text-white mt-1 leading-tight\">Headline</h2>\n        </div>\n        <button onclick=\"closeStoryModal()\" class=\"w-8 h-8 rounded-lg bg-slate-100 dark:bg-slate-800 text-slate-500 hover:text-slate-900 dark:hover:text-white font-bold flex items-center justify-center shrink-0\">\u2715</button>\n      </div>\n\n      <div id=\"story-modal-tickers-container\" class=\"flex items-center gap-1.5 flex-wrap\">\n        <!-- Tickers -->\n      </div>\n\n      <!-- \u26a1 EXECUTIVE GIST (INDIGO CARD) -->\n      <div class=\"p-3 rounded-xl bg-indigo-50/80 dark:bg-[#10182E] border border-indigo-200/90 dark:border-indigo-800 shadow-2xs\">\n        <p class=\"text-[11px] font-mono uppercase tracking-wider font-extrabold text-indigo-950 dark:text-indigo-300 mb-1 flex items-center gap-1\">\n          <span>\u26a1</span> <span>1. Executive Gist (Core Takeaway)</span>\n        </p>\n        <div id=\"story-modal-brief\" class=\"space-y-1.5\"></div>\n      </div>\n\n      <!-- \ud83d\udca1 TRADER CATALYST (DYNAMIC EMERALD/ROSE/SLATE CARD - DIRECTLY BELOW GIST) -->\n      <div id=\"story-modal-catalyst-box\" class=\"p-3 rounded-xl border border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-[#11172A] shadow-2xs\">\n        <p class=\"text-[11px] font-mono uppercase tracking-wider font-bold text-slate-600 dark:text-slate-300 mb-1 flex items-center gap-1\">\n          <span>\ud83d\udca1</span> <span>2. Trader Catalyst & Market Impact</span>\n        </p>\n        <div id=\"story-modal-catalyst\" class=\"text-xs text-slate-800 dark:text-slate-200 leading-relaxed font-medium bg-white dark:bg-[#0B1020] p-2.5 rounded-lg border border-slate-200/80 dark:border-slate-800\"></div>\n      </div>\n\n      <!-- \ud83d\udccc KEY ANALYST DATA POINTS (NEWSPAPER BROADSHEET CARD) -->\n      <div class=\"p-3 rounded-xl bg-[#F5EFEB] dark:bg-[#1E1914]/70 border border-[#B8A38E]/80 dark:border-[#524434] shadow-2xs\">\n        <p class=\"text-[11px] font-mono uppercase tracking-wider font-extrabold text-[#2E1F14] dark:text-[#F3ECE4] mb-1.5 flex items-center gap-1\">\n          <span>\ud83d\udccc</span> <span>3. Key Analyst Data Points</span>\n        </p>\n        <ul id=\"story-modal-bullets\" class=\"space-y-1.5\">\n          <!-- Bullets -->\n        </ul>\n      </div>\n\n      <div class=\"flex items-center justify-between pt-2 border-t border-slate-100 dark:border-slate-800 text-xs font-mono text-slate-400\">\n        <span id=\"story-modal-source\">FinPress Intelligence</span>\n        <button onclick=\"closeStoryModal()\" class=\"px-4 py-1.5 bg-brand-600 hover:bg-brand-700 text-white font-bold rounded-lg transition-colors\">Close</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- ================= IPO FULL DETAILS MODAL ================= -->\n  <div id=\"ipo-modal\" class=\"fixed inset-0 z-50 bg-black/60 backdrop-blur-xs hidden items-center justify-center p-4\">\n    <div class=\"bg-white dark:bg-[#0E1322] border border-slate-200 dark:border-slate-800 rounded-2xl max-w-2xl w-full p-6 shadow-2xl flex flex-col gap-4\">\n      <div class=\"flex items-start justify-between border-b border-slate-100 dark:border-slate-800 pb-3\">\n        <div>\n          <div class=\"flex items-center gap-2\">\n            <span id=\"modal-ipo-exchange\" class=\"px-2 py-0.5 rounded text-[10.5px] font-mono font-bold bg-indigo-50 text-indigo-700 border border-indigo-200 dark:bg-indigo-950/60 dark:text-indigo-300\">NSE / BSE</span>\n            <span id=\"modal-ipo-stage\" class=\"px-2 py-0.5 rounded text-[10.5px] font-mono font-bold bg-amber-50 text-amber-800 border border-amber-200\">DRHP Filed</span>\n          </div>\n          <h2 id=\"modal-ipo-company\" class=\"text-xl font-extrabold text-slate-900 dark:text-white mt-1\">Company Name</h2>\n        </div>\n        <button onclick=\"closeIpoModal()\" class=\"w-8 h-8 rounded-lg bg-slate-100 dark:bg-slate-800 text-slate-500 hover:text-slate-900 dark:hover:text-white font-bold flex items-center justify-center\">\u2715</button>\n      </div>\n\n      <div class=\"grid grid-cols-2 gap-3 bg-slate-50 dark:bg-[#151B2E] p-3 rounded-xl border border-slate-200/80 dark:border-slate-800 font-mono text-xs\">\n        <div>\n          <span class=\"text-slate-400\">Issue Size:</span>\n          <p id=\"modal-ipo-size\" class=\"text-slate-900 dark:text-white font-bold text-sm\">\u20b90 Cr</p>\n        </div>\n        <div>\n          <span class=\"text-slate-400\">Demand / Subscription:</span>\n          <p id=\"modal-ipo-demand\" class=\"text-emerald-600 dark:text-emerald-400 font-bold text-sm\">Filing Stage</p>\n        </div>\n      </div>\n\n      <div>\n        <p class=\"text-[11px] font-mono uppercase tracking-wider font-bold text-slate-400 mb-1\">Headline & Filing Announcement</p>\n        <p id=\"modal-ipo-headline\" class=\"text-sm font-bold text-slate-800 dark:text-slate-200\"></p>\n      </div>\n\n      <div>\n        <p class=\"text-[11px] font-mono uppercase tracking-wider font-bold text-brand-600 dark:text-brand-400 mb-1\">Detailed Analyst Insight & Comprehensive Notes</p>\n        <p id=\"modal-ipo-details\" class=\"text-sm text-slate-700 dark:text-slate-300 leading-relaxed bg-slate-50 dark:bg-[#11172A] p-3.5 rounded-xl border border-slate-200/80 dark:border-slate-800\"></p>\n      </div>\n\n      <div class=\"flex items-center justify-between pt-2 border-t border-slate-100 dark:border-slate-800 text-xs font-mono text-slate-400\">\n        <span id=\"modal-ipo-source\">Source: FE / BS</span>\n        <button onclick=\"closeIpoModal()\" class=\"px-4 py-1.5 bg-brand-600 hover:bg-brand-700 text-white font-bold rounded-lg transition-colors\">Close</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- ================= CLIENT JAVASCRIPT ================= -->\n  <script>\n    let rawReport = null;\n    let stories = [];\n    let ipoList = [];\n    let currentView = \"feed\";\n    let selectedFeedCategory = \"ALL\";\n    let selectedFeedSentiment = \"ALL\";\n    let activeStockFilter = null;\n    let activeSectorFilter = null;\n    let selectedStoryIndex = 0;\n    let currentFeedPage = 1;\n    const FEED_PAGE_SIZE = 12;\n    let currentIpoFilter = \"ALL\";\n    let currentSearchQuery = \"\";\n    let availableDates = [];\n    let currentDateIndex = 0;\n\n    const allowedSections = [\n      \"ALL\", \"Sector\", \"Economy\", \"Policy\", \"Market\", \"Trade\", \"International News\", \"Others\"\n    ];\n\n    const stockDictionary = [\n      \"RELIANCE\", \"TCS\", \"INFOSYS\", \"INFY\", \"HDFC BANK\", \"HDFCBANK\", \"ICICI BANK\", \"ICICIBANK\", \"SBI\", \"SBIN\",\n      \"BHARTI AIRTEL\", \"AIRTEL\", \"ITC\", \"KOTAK BANK\", \"L&T\", \"LT\", \"TATA MOTORS\", \"TATA STEEL\", \"TATA SONS\", \"TATA TRUSTS\",\n      \"MARUTI\", \"SUN PHARMA\", \"TITAN\", \"BAJAJ FINANCE\", \"ADANI\", \"NTPC\", \"ONGC\", \"POWERGRID\", \"JSW STEEL\", \"COAL INDIA\",\n      \"COALINDIA\", \"SAIL\", \"BCCL\", \"NCL\", \"HINDALCO\", \"WIPRO\", \"TECH MAHINDRA\", \"ZOMATO\", \"PAYTM\", \"SWIGGY\",\n      \"OLA ELECTRIC\", \"OLA ELEC\", \"HAL\", \"BEL\", \"BHEL\", \"BDL\", \"IRFC\", \"RVNL\", \"IREDA\", \"VEDANTA\", \"DLF\", \"GODREJ\",\n      \"AXIS BANK\", \"ASIAN PAINTS\", \"ULTRATECH\", \"HERO MOTOCORP\", \"BAJAJ AUTO\", \"EICHER\", \"DR REDDY\", \"CIPLA\", \"TRENT\",\n      \"DMART\", \"POLYCAB\", \"DIXON\", \"BSE\", \"MCX\", \"CDSL\", \"AIR INDIA\", \"COFORGE\", \"V-GUARD\", \"HCLTECH\", \"AROVIA\",\n      \"EDELWEISS\", \"NATCO PHARMA\", \"GUJARAT THEMIS\", \"ORACLE\", \"NATRAJ ENERGY\", \"ESDS SOFTWARE\", \"INDO-MIM\", \"SAGARMALA\",\n      \"ALIBABA\", \"BYTEDANCE\", \"NVIDIA\", \"JIO\", \"NAYARA\", \"FIRESIDE\", \"META\", \"MONGODB\"\n    ];\n\n    const sectorDictionary = [\n      \"ENERGY\", \"POWER\", \"IT\", \"TECH\", \"REAL ESTATE\", \"REALTY\", \"BANKING\", \"FINANCE\", \"AUTO\", \"AUTOMOTIVE\", \"EV\",\n      \"PHARMA\", \"HEALTHCARE\", \"DEFENCE\", \"METALS\", \"STEEL\", \"MINING\", \"TELECOM\", \"FMCG\", \"CONSUMER\", \"INFRASTRUCTURE\",\n      \"INFRA\", \"AVIATION\", \"LOGISTICS\", \"CHEMICALS\", \"TEXTILES\", \"AGRICULTURE\", \"INSURANCE\", \"MEDIA\", \"RETAIL\"\n    ];\n\n    \n    let isSidebarVisible = localStorage.getItem('finpress_sidebar_visible') !== 'false';\n\n    function toggleSidebar() {\n      isSidebarVisible = !isSidebarVisible;\n      localStorage.setItem('finpress_sidebar_visible', isSidebarVisible);\n      applySidebarVisibility();\n    }\n\n    function applySidebarVisibility() {\n      const aside = document.getElementById(\"view-feed-aside\");\n      const pill = document.getElementById(\"sidebar-vertical-pill\");\n      const viewFeed = document.getElementById(\"view-feed\");\n      const openBtn = document.getElementById(\"feed-open-sidebar-btn\");\n\n      if (aside && viewFeed) {\n        if (isSidebarVisible) {\n          aside.classList.remove(\"hidden\");\n          if (pill) pill.classList.add(\"hidden\");\n          viewFeed.className = \"grid grid-cols-1 lg:grid-cols-[280px_minmax(0,1fr)_260px] xl:grid-cols-[300px_minmax(0,1fr)_275px] gap-2.5 items-start\";\n          if (openBtn) {\n            openBtn.classList.add(\"hidden\");\n            openBtn.classList.remove(\"flex\");\n          }\n        } else {\n          aside.classList.add(\"hidden\");\n          if (pill) pill.classList.remove(\"hidden\");\n          viewFeed.className = \"grid grid-cols-1 lg:grid-cols-[280px_minmax(0,1fr)_auto] xl:grid-cols-[300px_minmax(0,1fr)_auto] gap-2.5 items-start\";\n          if (openBtn) {\n            openBtn.classList.remove(\"hidden\");\n            openBtn.classList.add(\"flex\");\n          }\n        }\n      }\n    }\n\n    function initTheme() {\n      const t = localStorage.getItem('finbrief_theme') || 'light';\n      applyTheme(t);\n    }\n    function toggleTheme() {\n      const isDark = document.documentElement.classList.contains('dark');\n      const next = isDark ? 'light' : 'dark';\n      applyTheme(next);\n      localStorage.setItem('finbrief_theme', next);\n    }\n    function applyTheme(t) {\n      const icon = document.getElementById('theme-icon');\n      if (t === 'dark') {\n        document.documentElement.classList.add('dark');\n        if (icon) icon.textContent = '\u2600\ufe0f';\n      } else {\n        document.documentElement.classList.remove('dark');\n        if (icon) icon.textContent = '\ud83c\udf19';\n      }\n    }\n\n    let currentFontScale = 100;\n    function initFontSize() {\n      const saved = localStorage.getItem('finpress_font_scale');\n      if (saved) {\n        currentFontScale = parseInt(saved, 10) || 100;\n      }\n      applyFontSize(currentFontScale);\n    }\n    function adjustFontSize(delta) {\n      currentFontScale = Math.min(130, Math.max(85, currentFontScale + (delta * 5)));\n      localStorage.setItem('finpress_font_scale', currentFontScale);\n      applyFontSize(currentFontScale);\n    }\n    function applyFontSize(scale) {\n      const label = document.getElementById(\"font-size-label\");\n      if (label) label.textContent = `${scale}%`;\n      document.body.style.zoom = `${scale}%`;\n      document.documentElement.style.fontSize = `${(scale / 100) * 100}%`;\n    }\n\n    let currentLayoutMode = \"split\";\n\n    function setViewMode(mode) {\n      currentLayoutMode = mode;\n      const splitBtn = document.getElementById(\"mode-split-btn\");\n      const matrixBtn = document.getElementById(\"mode-matrix-btn\");\n      const viewFeed = document.getElementById(\"view-feed\");\n      const viewMatrix = document.getElementById(\"view-matrix\");\n\n      if (splitBtn) splitBtn.className = mode === \"split\" ? \"px-2 py-0.5 rounded bg-indigo-600 text-white shadow-xs\" : \"px-2 py-0.5 rounded text-slate-300 hover:text-white\";\n      if (matrixBtn) matrixBtn.className = mode === \"matrix\" ? \"px-2 py-0.5 rounded bg-indigo-600 text-white shadow-xs\" : \"px-2 py-0.5 rounded text-slate-300 hover:text-white\";\n\n      if (currentView === \"ipo\") return;\n\n      if (mode === \"split\") {\n        viewFeed.classList.remove(\"hidden\");\n        viewFeed.classList.add(\"grid\");\n        viewMatrix.classList.add(\"hidden\");\n        viewMatrix.classList.remove(\"flex\");\n        renderFeedList();\n      } else {\n        viewFeed.classList.add(\"hidden\");\n        viewFeed.classList.remove(\"grid\");\n        viewMatrix.classList.remove(\"hidden\");\n        viewMatrix.classList.add(\"flex\");\n        renderMatrixTable();\n      }\n    }\n\n    function switchView(viewName) {\n      currentView = viewName;\n      const tabAnchor = document.getElementById(\"tab-btn-anchor\");\n      const viewFeed = document.getElementById(\"view-feed\");\n      const corpBanner = document.getElementById(\"corporate-subtabs-banner\");\n      const ipoBanner = document.getElementById(\"ipo-subtabs-banner\");\n      const deskSelect = document.getElementById(\"desk-select\");\n      const categorySelect = document.getElementById(\"category-select\");\n\n      selectedStoryIndex = 0;\n      currentFeedPage = 1;\n\n      if (tabAnchor) tabAnchor.className = \"px-2.5 py-1 rounded-md transition-all text-slate-800 dark:text-slate-300 hover:text-black dark:hover:text-white hover:bg-white/60 dark:hover:bg-slate-800 flex items-center gap-1.5 font-medium\";\n\n      viewFeed.classList.remove(\"hidden\");\n      viewFeed.classList.add(\"grid\");\n\n      if (viewName === \"feed\") {\n        selectedFeedCategory = \"ALL\";\n        if (categorySelect) categorySelect.value = \"ALL\";\n        if (deskSelect) deskSelect.value = \"\";\n        if (corpBanner) corpBanner.classList.add(\"hidden\");\n        if (ipoBanner) ipoBanner.classList.add(\"hidden\");\n      } else if (viewName === \"anchor\") {\n        if (tabAnchor) tabAnchor.className = \"px-2.5 py-1 rounded-md transition-all bg-[#1C1917] text-[#FFF8F0] dark:bg-indigo-600 dark:text-white shadow-xs flex items-center gap-1.5 font-semibold\";\n        selectedFeedCategory = \"ANCHOR\";\n        if (deskSelect) deskSelect.value = \"\";\n        if (corpBanner) corpBanner.classList.add(\"hidden\");\n        if (ipoBanner) ipoBanner.classList.add(\"hidden\");\n      } else if (viewName === \"ipo\") {\n        if (deskSelect) deskSelect.value = \"ipo\";\n        if (corpBanner) corpBanner.classList.add(\"hidden\");\n        if (ipoBanner) {\n          ipoBanner.classList.remove(\"hidden\");\n          ipoBanner.classList.add(\"flex\");\n          selectIpoSub(\"ALL\");\n          return;\n        }\n      } else if (viewName === \"corporate\") {\n        if (deskSelect) deskSelect.value = \"corporate\";\n        if (ipoBanner) ipoBanner.classList.add(\"hidden\");\n        if (corpBanner) {\n          corpBanner.classList.remove(\"hidden\");\n          corpBanner.classList.add(\"flex\");\n          selectCorporateSub(\"ALL\");\n          return;\n        }\n      } else if (viewName === \"opinions\") {\n        if (deskSelect) deskSelect.value = \"opinions\";\n        selectedFeedCategory = \"OPINIONS\";\n        if (corpBanner) corpBanner.classList.add(\"hidden\");\n        if (ipoBanner) ipoBanner.classList.add(\"hidden\");\n      }\n\n      renderFeedList();\n    }\n\n    function onDeskSelect(val) {\n      if (!val) return;\n      if (val === \"ipo\") {\n        switchView(\"ipo\");\n      } else if (val === \"corporate\") {\n        switchView(\"corporate\");\n      } else if (val === \"opinions\") {\n        switchView(\"opinions\");\n      }\n    }\n\n    function selectIpoSub(sub) {\n      if (sub === 'ALL') {\n        selectedFeedCategory = \"IPO_ALL\";\n      } else if (sub === 'DRHP') {\n        selectedFeedCategory = \"IPO_DRHP\";\n      } else if (sub === 'BIDDING') {\n        selectedFeedCategory = \"IPO_BIDDING\";\n      } else if (sub === 'NOTICES') {\n        selectedFeedCategory = \"IPO_NOTICES\";\n      }\n      \n      const subLower = sub.toLowerCase();\n      [\"all\", \"drhp\", \"bidding\", \"notices\"].forEach(t => {\n        const btn = document.getElementById(`ipo-tab-${t}`);\n        if (btn) {\n          if (t === subLower) {\n            btn.className = \"px-3 py-1 rounded-md bg-[#1C1917] text-[#FFF8F0] dark:bg-indigo-600 dark:text-white shadow-xs transition-all flex items-center gap-1.5 font-semibold\";\n          } else {\n            btn.className = \"px-3 py-1 rounded-md text-slate-800 dark:text-slate-300 hover:text-black dark:hover:text-white hover:bg-white/60 dark:hover:bg-slate-800 transition-all flex items-center gap-1.5 font-medium\";\n          }\n        }\n      });\n      selectedStoryIndex = 0;\n      currentFeedPage = 1;\n      renderFeedList();\n    }\n\n    function selectCorporateSub(sub) {\n      if (sub === 'ALL') {\n        selectedFeedCategory = \"CORPORATE_ALL\";\n      } else if (sub === 'EVENTS') {\n        selectedFeedCategory = \"EVENTS\";\n      } else if (sub === 'APPOINTMENTS') {\n        selectedFeedCategory = \"APPOINTMENTS\";\n      }\n      \n      const subLower = sub === 'ALL' ? 'all' : sub === 'EVENTS' ? 'events' : 'appts';\n      [\"all\", \"events\", \"appts\"].forEach(t => {\n        const btn = document.getElementById(`corp-tab-${t}`);\n        if (btn) {\n          if (t === subLower) {\n            btn.className = \"px-3 py-1 rounded-md bg-[#1C1917] text-[#FFF8F0] dark:bg-indigo-600 dark:text-white shadow-xs transition-all flex items-center gap-1.5 font-semibold\";\n          } else {\n            btn.className = \"px-3 py-1 rounded-md text-slate-800 dark:text-slate-300 hover:text-black dark:hover:text-white hover:bg-white/60 dark:hover:bg-slate-800 transition-all flex items-center gap-1.5 font-medium\";\n          }\n        }\n      });\n      selectedStoryIndex = 0;\n      currentFeedPage = 1;\n      renderFeedList();\n    }\n\n    function onCategorySelect(val) {\n      selectedStoryIndex = 0;\n      currentFeedPage = 1;\n      selectedFeedCategory = val;\n      \n      const deskSelect = document.getElementById(\"desk-select\");\n      if (deskSelect) deskSelect.value = \"\";\n      \n      const corpBanner = document.getElementById(\"corporate-subtabs-banner\");\n      if (corpBanner) corpBanner.classList.add(\"hidden\");\n      const ipoBanner = document.getElementById(\"ipo-subtabs-banner\");\n      if (ipoBanner) ipoBanner.classList.add(\"hidden\");\n      \n      const tabAnchor = document.getElementById(\"tab-btn-anchor\");\n      if (tabAnchor) tabAnchor.className = \"px-2.5 py-1 rounded-md transition-all text-slate-800 dark:text-slate-300 hover:text-black dark:hover:text-white hover:bg-white/60 dark:hover:bg-slate-800 flex items-center gap-1.5 font-medium\";\n      \n      const catSelect = document.getElementById(\"category-select\");\n      if (catSelect && val !== \"ALL\" && !val.startsWith(\"IPO\") && !val.startsWith(\"CORPORATE\") && val !== \"OPINIONS\" && val !== \"ANCHOR\") {\n        catSelect.value = val;\n      } else if (catSelect && val === \"ALL\") {\n        catSelect.value = \"ALL\";\n      }\n\n      renderCategoriesAndStocksSidebar();\n      renderFeedList();\n    }\n\n    function isFillerHeadline(hl) {\n      const h = hl.toLowerCase();\n      return (\n        h.includes(\"special edition and general overview\") ||\n        h.includes(\"general overview\") ||\n        h.includes(\"newspaper overview\") ||\n        h.includes(\"sunday special edition\") ||\n        h.includes(\"fe sunday special\") ||\n        h.includes(\"edition overview\") ||\n        h.includes(\"e-paper index\") ||\n        h.includes(\"table of contents\")\n      );\n    }\n\n    function parseStory(story, idx) {\n      if (isFillerHeadline(story.headline)) return null;\n\n      const fullText = (story.headline + \" \" + story.brief_details + \" \" + (story.bullet_points || []).join(\" \")).toLowerCase();\n      const pageStr = (story.page_numbers || \"\").toLowerCase();\n\n      // Strict Market Section Rule: Bank disclosures/Statutory notices belong in Corporate Events\n      let category = story.category;\n      if (category === \"Market\" || category === \"Others\") {\n        const noticeTerms = [\"disclosure\", \"public notice\", \"statutory notice\", \"possession notice\", \"postal ballot\", \"e-voting\", \"annual general meeting\", \"agm notice\", \"egm notice\", \"co-op bank\", \"co-operative bank\", \"financial and regulatory disclosure\", \"auction notice\"];\n        if (noticeTerms.some(t => fullText.includes(t))) {\n          category = \"Corporate Events\";\n        }\n      }\n\n      // Detect Opinions / Editorial\n      const isOpinion = pageStr.includes(\"opinion\") || pageStr.includes(\"edit\") || pageStr.includes(\"column\") || pageStr.includes(\"commentary\") || fullText.includes(\"op-ed\") || fullText.includes(\"editorial view\");\n\n      // Strict Front Page Anchors: Must be Page 1 and strictly genuine NEWS (NOT IPOs, Corporate Announcements, or Disclosures)\n      const isPage1Location = pageStr.includes(\"page 1\") || pageStr.includes(\"page 01\") || pageStr.includes(\"p.1\") || pageStr.includes(\"front\") || pageStr.includes(\"lead\");\n      const isAnnouncementOrIpo = category === \"IPO\" || category === \"Corporate Events\" || category === \"Corporate Appointments\" || isOpinion || fullText.includes(\"drhp\") || fullText.includes(\"statutory notice\") || fullText.includes(\"public notice\") || fullText.includes(\"disclosure\");\n      const isFrontPage = (isPage1Location || idx < 4) && !isAnnouncementOrIpo;\n\n      let ipoData = null;\n      if (category === \"IPO\") {\n        ipoData = parseIpoItem(story, idx);\n      }\n\n      const bullishTriggers = [\n        { k: \"order win\", r: \"Contract / Order Inflow expands near-term revenue visibility.\" },\n        { k: \"mou\", r: \"Strategic MoU / Partnership accelerates joint development and market reach.\" },\n        { k: \"expansion\", r: \"Capacity Expansion / New facility enhances long-term operational throughput.\" },\n        { k: \"profit up\", r: \"Strong bottom-line growth signals healthy operational leverage.\" },\n        { k: \"revenue up\", r: \"Topline growth indicates robust market demand and pricing power.\" },\n        { k: \"approval\", r: \"Key regulatory/government clearance removes project bottleneck.\" },\n        { k: \"dividend\", r: \"Shareholder payout / capital return signals healthy balance-sheet liquidity.\" },\n        { k: \"exemption\", r: \"Policy duty waiver / tax exemption improves gross margins.\" },\n        { k: \"surge\", r: \"Sharp positive volume/demand breakout across core business segments.\" }\n      ];\n\n      const bearishRisks = [\n        { k: \"penalty\", r: \"Regulatory penalty / Show-cause notice creates near-term compliance headwind.\" },\n        { k: \"fine\", r: \"Monetary penalty imposes financial liability and compliance friction.\" },\n        { k: \"probe\", r: \"Regulatory/tax scrutiny introduces headline risk and governance scrutiny.\" },\n        { k: \"loss\", r: \"Widening losses or margin compression weigh on fundamental valuation.\" },\n        { k: \"slump\", r: \"Demand deceleration or volume contraction creates earnings drag.\" },\n        { k: \"falls\", r: \"Topline or net margin contraction signals weakening operating leverage.\" },\n        { k: \"tax hike\", r: \"Increased duty/tax burdens directly compress profit spreads.\" },\n        { k: \"curb\", r: \"Export/import curbs or policy restrictions limit addressable business.\" }\n      ];\n\n      let matchedBullish = [];\n      bullishTriggers.forEach(t => { if (fullText.includes(t.k)) matchedBullish.push(t.r); });\n\n      let matchedBearish = [];\n      bearishRisks.forEach(t => { if (fullText.includes(t.k)) matchedBearish.push(t.r); });\n\n      let sentiment = \"NEUTRAL\";\n      let sentimentReasoning = \"Baseline monitoring trigger: Ongoing operational development, sector-wide baseline trend, or corporate filing to track for subsequent quarterly performance.\";\n\n      if (matchedBullish.length > matchedBearish.length) {\n        sentiment = \"BULLISH\";\n        sentimentReasoning = matchedBullish.slice(0, 2).join(\" Additionally, \");\n      } else if (matchedBearish.length > matchedBullish.length) {\n        sentiment = \"BEARISH\";\n        sentimentReasoning = matchedBearish.slice(0, 2).join(\" Additionally, \");\n      }\n\n      const detectedStocks = [];\n      const detectedSectors = [];\n      const upperText = (story.headline + \" \" + story.brief_details + \" \" + (story.bullet_points || []).join(\" \")).toUpperCase();\n\n      stockDictionary.forEach(stk => {\n        if (new RegExp(`\\\\b${stk.replace('&', '\\\\&')}\\\\b`, 'i').test(upperText)) {\n          detectedStocks.push(stk);\n        }\n      });\n\n      sectorDictionary.forEach(sec => {\n        if (new RegExp(`\\\\b${sec.replace('&', '\\\\&')}\\\\b`, 'i').test(upperText)) {\n          detectedSectors.push(sec);\n        }\n      });\n\n      let catalyst = (story.bullet_points && story.bullet_points.length > 0) ? story.bullet_points[0] : story.brief_details.slice(0, 160) + \"...\";\n\n      const uniqueStocks = [...new Set(detectedStocks)].slice(0, 3);\n      const uniqueSectors = [...new Set(detectedSectors)].slice(0, 3);\n      const allTickers = [...new Set([...uniqueStocks, ...uniqueSectors])].slice(0, 4);\n\n      return {\n        ...story,\n        id: idx + 1,\n        category: category || \"Others\",\n        sentiment,\n        sentimentReasoning,\n        stocks: uniqueStocks,\n        sectors: uniqueSectors,\n        tickers: allTickers,\n        catalyst,\n        isFrontPage,\n        isOpinion,\n        ipoTag: ipoData ? ipoData.filterTag : null,\n        ipoData: ipoData\n      };\n    }\n\n    function parseIpoItem(s, idx) {\n      const h = s.headline;\n      const d = s.brief_details;\n      const combined = (h + \" \" + d).toLowerCase();\n\n      let company = h.replace(/public announcement|basis of allotment|files ipo papers|files draft ipo papers|ipo subscribed|files for|shelves|amid market uncertainty/gi, '').trim();\n      company = company.replace(/^(biscuit maker|nine firms filing ipo papers with sebi:|after reverse flip to india: cfo)/gi, '').trim();\n      if (company.length > 32) company = company.slice(0, 32) + '...';\n\n      let size = \"Not Disclosed\";\n      const sizeMatch = (h + \" \" + d).match(/(?:\u20b9|\u2090|rs\\.?)\\s?([\\d,]+(?:\\.\\d+)?)\\s?(?:cr|crore|lakh)/i);\n      if (sizeMatch) size = `\u20b9${sizeMatch[1]} Cr`;\n      else if (combined.includes(\"fresh issue\")) size = \"Fresh Issue\";\n      else if (combined.includes(\"sme\")) size = \"SME Issue\";\n\n      // Detect Target Listing Exchange\n      let exchange = \"NSE / BSE Mainboard\";\n      if (combined.includes(\"sme\") || combined.includes(\"emerge\")) {\n        exchange = \"NSE Emerge / BSE SME\";\n      } else if (combined.includes(\"bse only\") || combined.includes(\"bse startup\")) {\n        exchange = \"BSE Only\";\n      }\n\n      let stage = \"\ud83d\udccb DRHP Filed\";\n      let stageBadge = \"bg-amber-50 text-amber-800 border-amber-200 dark:bg-amber-950/40 dark:text-amber-300\";\n      let filterTag = \"DRHP\";\n\n      if (combined.includes(\"subscribed\")) {\n        stage = \"\ud83d\udcc8 Active Bidding\";\n        stageBadge = \"bg-emerald-50 text-emerald-800 border-emerald-200 dark:bg-emerald-950/40 dark:text-emerald-300\";\n        filterTag = \"BIDDING\";\n      } else if (combined.includes(\"allotment\") || combined.includes(\"basis\")) {\n        stage = \"\ud83c\udfdb\ufe0f Allotment Out\";\n        stageBadge = \"bg-blue-50 text-blue-800 border-blue-200 dark:bg-blue-950/40 dark:text-blue-300\";\n        filterTag = \"NOTICES\";\n      } else if (combined.includes(\"shelve\") || combined.includes(\"delay\")) {\n        stage = \"\u23f8\ufe0f Deferred\";\n        stageBadge = \"bg-rose-50 text-rose-800 border-rose-200 dark:bg-rose-950/40 dark:text-rose-300\";\n        filterTag = \"DRHP\";\n      } else if (combined.includes(\"announcement\") || combined.includes(\"notice\")) {\n        stage = \"\ud83d\udce2 Public Issue Notice\";\n        stageBadge = \"bg-purple-50 text-purple-800 border-purple-200 dark:bg-purple-950/40 dark:text-purple-300\";\n        filterTag = \"NOTICES\";\n      }\n\n      let demand = \"Filing Stage\";\n      const subMatch = (h + \" \" + d).match(/subscribed\\s+([\\d\\.]+)\\s+(?:times|x)/i);\n      const subPctMatch = (h + \" \" + d).match(/subscribed\\s+([\\d\\.]+%)/i);\n      if (subMatch) demand = `${subMatch[1]}x Subscribed`;\n      else if (subPctMatch) demand = `${subPctMatch[1]} Subscribed`;\n      else if (stage.includes(\"Allotment\")) demand = \"Completed\";\n\n      return {\n        id: idx + 1,\n        headline: h,\n        company: company || h.slice(0, 25),\n        size,\n        exchange,\n        stage,\n        stageBadge,\n        filterTag,\n        demand,\n        details: d,\n        source: s.page_numbers || \"FE / BS\"\n      };\n    }\n\n    async function fetchDates() {\n      try {\n        const res = await fetch(`/api/dates?t=${Date.now()}`);\n        if (res.ok) {\n          availableDates = await res.json();\n          if (availableDates && availableDates.length > 0) {\n            const picker = document.getElementById(\"calendar-picker\");\n            if (rawReport && rawReport.edition_date) {\n              if (picker) picker.value = rawReport.edition_date;\n            } else if (picker) {\n              picker.value = availableDates[0];\n            }\n          }\n        }\n      } catch (e) {}\n    }\n\n    function navigateDate(dir) {\n      if (!availableDates || availableDates.length === 0) return;\n      currentDateIndex += dir;\n      if (currentDateIndex < 0) currentDateIndex = 0;\n      if (currentDateIndex >= availableDates.length) currentDateIndex = availableDates.length - 1;\n      const target = availableDates[currentDateIndex];\n      const picker = document.getElementById(\"calendar-picker\");\n      if (picker) picker.value = target;\n      loadData(target);\n    }\n\n    function onCalendarSelect(val) {\n      if (!val) return;\n      if (availableDates.includes(val)) {\n        currentDateIndex = availableDates.indexOf(val);\n      }\n      loadData(val);\n    }\n\n    async function onDateChange(selectedDate) {\n      const picker = document.getElementById(\"calendar-picker\");\n      if (picker) picker.value = selectedDate;\n      await loadData(selectedDate);\n    }\n\n    async function loadData(targetDate = null) {\n      try {\n        const endpoint = targetDate ? `/api/report?date=${targetDate}&t=${Date.now()}` : `/api/report?t=${Date.now()}`;\n        const res = await fetch(endpoint);\n        if (!res.ok) throw new Error(\"Failed\");\n        rawReport = await res.json();\n      } catch (e) {\n        try {\n          const fallbackUrl = targetDate \n            ? `https://pub-c81167dd545d49d0a2cd964a8bd6a1cd.r2.dev/reports/news_report_unified_${targetDate}.json?t=${Date.now()}`\n            : `https://pub-c81167dd545d49d0a2cd964a8bd6a1cd.r2.dev/reports/news_report_unified_latest.json?t=${Date.now()}`;\n          const res = await fetch(fallbackUrl);\n          rawReport = await res.json();\n        } catch (err) {}\n      }\n\n      if (rawReport && rawReport.major_stories) {\n        const edDate = rawReport.edition_date;\n        const dateInput = document.getElementById(\"calendar-picker\");\n        if (dateInput && edDate) dateInput.value = edDate;\n        if (availableDates.includes(edDate)) {\n          currentDateIndex = availableDates.indexOf(edDate);\n        }\n\n        stories = rawReport.major_stories\n          .map((s, idx) => parseStory(s, idx))\n          .filter(Boolean);\n\n        const rawIpos = stories.filter(s => s.category === \"IPO\");\n        ipoList = rawIpos.map((s, idx) => s.ipoData || parseIpoItem(s, idx));\n        initMetrics();\n        applySidebarVisibility();\n      }\n    }\n\n    function updateDropdownOptions(coreCount, ipoCount, corpCount, opCount) {\n      const catSelect = document.getElementById(\"category-select\");\n      if (catSelect) {\n        const counts = {\n          Sector: stories.filter(s => s.category === \"Sector\" && !s.isOpinion).length,\n          Economy: stories.filter(s => s.category === \"Economy\" && !s.isOpinion).length,\n          Policy: stories.filter(s => s.category === \"Policy\" && !s.isOpinion).length,\n          Market: stories.filter(s => s.category === \"Market\" && !s.isOpinion).length,\n          Trade: stories.filter(s => s.category === \"Trade\" && !s.isOpinion).length,\n          \"International News\": stories.filter(s => s.category === \"International News\" && !s.isOpinion).length,\n          Others: stories.filter(s => s.category === \"Others\" && !s.isOpinion).length\n        };\n        catSelect.innerHTML = `\n          <option value=\"ALL\">\u26a1 All News (${coreCount})</option>\n          <option value=\"Sector\">Sector (${counts.Sector})</option>\n          <option value=\"Economy\">Economy (${counts.Economy})</option>\n          <option value=\"Policy\">Policy (${counts.Policy})</option>\n          <option value=\"Market\">Market (${counts.Market})</option>\n          <option value=\"Trade\">Trade & FX (${counts.Trade})</option>\n          <option value=\"International News\">International (${counts[\"International News\"]})</option>\n          <option value=\"Others\">General Features (${counts.Others})</option>\n        `;\n        if (selectedFeedCategory !== \"ANCHOR\" && !selectedFeedCategory.startsWith(\"CORPORATE\") && !selectedFeedCategory.startsWith(\"IPO\") && selectedFeedCategory !== \"OPINIONS\") {\n          catSelect.value = selectedFeedCategory;\n        } else {\n          catSelect.value = \"ALL\";\n        }\n      }\n\n      const deskSelect = document.getElementById(\"desk-select\");\n      if (deskSelect) {\n        deskSelect.innerHTML = `\n          <option value=\"\" disabled ${currentView === 'feed' && selectedFeedCategory !== 'OPINIONS' && !selectedFeedCategory.startsWith('CORPORATE') && !selectedFeedCategory.startsWith('IPO') ? 'selected' : ''}>\ud83c\udfdb\ufe0f Specialized Desks \u25be</option>\n          <option value=\"ipo\" ${currentView === 'ipo' || selectedFeedCategory.startsWith('IPO') ? 'selected' : ''}>\ud83d\ude80 IPO Central (${ipoCount})</option>\n          <option value=\"corporate\" ${currentView === 'corporate' || selectedFeedCategory.startsWith('CORPORATE') ? 'selected' : ''}>\ud83c\udfe2 Corporate (${corpCount})</option>\n          <option value=\"opinions\" ${selectedFeedCategory === 'OPINIONS' ? 'selected' : ''}>\u270d\ufe0f Opinions (${opCount})</option>\n        `;\n      }\n    }\n\n    function initMetrics() {\n      // Core All News strictly excludes IPO, Corporate Events, Corporate Appointments, and Opinions\n      const coreStories = stories.filter(s => s.category !== \"IPO\" && s.category !== \"Corporate Events\" && s.category !== \"Corporate Appointments\" && !s.isOpinion);\n      const totalIpos = ipoList.length;\n      const anchorCount = coreStories.filter(s => s.isFrontPage).length;\n      const corpEventsCount = stories.filter(s => s.category === \"Corporate Events\").length;\n      const corpApptsCount = stories.filter(s => s.category === \"Corporate Appointments\").length;\n      const corpCount = corpEventsCount + corpApptsCount;\n      const opinionsCount = stories.filter(s => s.isOpinion).length;\n\n      const drhpCount = ipoList.filter(i => (i.stage || \"\").includes(\"DRHP\") || (i.filterTag || \"\") === \"DRHP\").length;\n      const biddingCount = ipoList.filter(i => (i.stage || \"\").includes(\"Bidding\") || (i.stage || \"\").includes(\"Open\") || (i.filterTag || \"\") === \"BIDDING\").length;\n      const noticesCount = totalIpos - drhpCount - biddingCount;\n\n      const topTotal = document.getElementById(\"top-total-count\");\n      if (topTotal) topTotal.textContent = stories.length;\n      const tabAnchor = document.getElementById(\"tab-anchor-count\");\n      if (tabAnchor) tabAnchor.textContent = anchorCount;\n\n      // Update IPO Sub-tab counts\n      const ipoSubAll = document.getElementById(\"ipo-sub-all-count\");\n      if (ipoSubAll) ipoSubAll.textContent = totalIpos;\n      const ipoSubDrhp = document.getElementById(\"ipo-sub-drhp-count\");\n      if (ipoSubDrhp) ipoSubDrhp.textContent = drhpCount;\n      const ipoSubBidding = document.getElementById(\"ipo-sub-bidding-count\");\n      if (ipoSubBidding) ipoSubBidding.textContent = biddingCount;\n      const ipoSubNotices = document.getElementById(\"ipo-sub-notices-count\");\n      if (ipoSubNotices) ipoSubNotices.textContent = noticesCount;\n\n      // Update Corporate Sub-tab counts\n      const corpSubAll = document.getElementById(\"corp-sub-all-count\");\n      if (corpSubAll) corpSubAll.textContent = corpCount;\n      const corpSubEvents = document.getElementById(\"corp-sub-events-count\");\n      if (corpSubEvents) corpSubEvents.textContent = corpEventsCount;\n      const corpSubAppts = document.getElementById(\"corp-sub-appts-count\");\n      if (corpSubAppts) corpSubAppts.textContent = corpApptsCount;\n\n      // Update Dropdowns with Section Numbers\n      updateDropdownOptions(coreStories.length, totalIpos, corpCount, opinionsCount);\n\n      let bCount = 0, rCount = 0;\n      coreStories.forEach(s => {\n        if (s.sentiment === \"BULLISH\") bCount++;\n        else if (s.sentiment === \"BEARISH\") rCount++;\n      });\n      const feedAll = document.getElementById(\"feed-count-all\");\n      if (feedAll) feedAll.textContent = coreStories.length;\n      const feedBullish = document.getElementById(\"feed-count-bullish\");\n      if (feedBullish) feedBullish.textContent = bCount;\n      const feedBearish = document.getElementById(\"feed-count-bearish\");\n      if (feedBearish) feedBearish.textContent = rCount;\n\n      // Render Source Pipeline Health\n      const healthContainer = document.getElementById(\"source-health-container\");\n      const alertBanner = document.getElementById(\"source-alert-banner\");\n      const alertText = document.getElementById(\"source-alert-text\");\n\n      if (healthContainer) {\n        healthContainer.innerHTML = \"\";\n        const statuses = (rawReport && rawReport.source_statuses) || {};\n        \n        let hasFailure = false;\n        let failureDetails = [];\n\n        const feStatus = statuses.financial_express || \"\u2705 FE (Active)\";\n        const bsStatus = statuses.business_standard || (stories.some(s => (s.page_numbers || \"\").includes(\"BS\")) ? \"\u2705 BS (Active)\" : \"\u274c BS (Session Expired)\");\n\n        const fePill = document.createElement(\"span\");\n        fePill.className = feStatus.includes(\"\u2705\") \n          ? \"px-1.5 py-0.2 rounded bg-slate-900 border border-slate-700 text-slate-300 font-bold\" \n          : \"px-1.5 py-0.2 rounded bg-rose-500/20 border border-rose-500/40 text-rose-300 font-bold\";\n        fePill.textContent = `FE: ${feStatus.includes(\"\u2705\") ? '\u2705' : '\u274c'}`;\n        fePill.title = `Financial Express: ${feStatus}`;\n        healthContainer.appendChild(fePill);\n\n        const bsPill = document.createElement(\"span\");\n        const bsOk = bsStatus.includes(\"\u2705\") || bsStatus.includes(\"Active\");\n        bsPill.className = bsOk \n          ? \"px-1.5 py-0.2 rounded bg-slate-900 border border-slate-700 text-slate-300 font-bold\" \n          : \"px-1.5 py-0.2 rounded bg-rose-500/20 border border-rose-500/40 text-rose-300 font-bold\";\n        bsPill.textContent = `BS: ${bsOk ? '\u2705' : '\u274c'}`;\n        bsPill.title = `Business Standard: ${bsStatus}`;\n        healthContainer.appendChild(bsPill);\n\n        if (!bsOk) {\n          hasFailure = true;\n          failureDetails.push(\"Business Standard subscriber session expired or was not authenticated. Showing Financial Express news.\");\n        }\n        if (!feStatus.includes(\"\u2705\")) {\n          hasFailure = true;\n          failureDetails.push(\"Financial Express edition failed to download.\");\n        }\n\n        if (hasFailure && alertBanner && alertText) {\n          alertText.innerHTML = `<b>Edition Notice:</b> ${failureDetails.join(\" \u00b7 \")}`;\n          alertBanner.classList.remove(\"hidden\");\n        } else if (alertBanner) {\n          alertBanner.classList.add(\"hidden\");\n        }\n      }\n\n      renderCategoriesAndStocksSidebar();\n      renderFeedList();\n    }\n\n    // ================= FILTER LOGIC =================\n    function getFilteredStories() {\n      const rawQuery = document.getElementById(\"global-search\").value.trim().toLowerCase();\n      const queryTokens = rawQuery ? rawQuery.split(/\\s+/).filter(Boolean) : [];\n      \n      return stories.filter(s => {\n        const searchableText = (\n          s.headline + \" \" + \n          s.brief_details + \" \" + \n          (s.bullet_points || []).join(\" \") + \" \" + \n          s.category + \" \" + \n          s.page_numbers + \" \" + \n          s.tickers.join(\" \")\n        ).toLowerCase();\n\n        const matchQuery = queryTokens.length === 0 || queryTokens.every(tok => searchableText.includes(tok));\n        \n        let matchSec = true;\n        if (selectedFeedCategory === \"ALL\") {\n          matchSec = s.category !== \"IPO\" && s.category !== \"Corporate Events\" && s.category !== \"Corporate Appointments\" && !s.isOpinion;\n        } else if (selectedFeedCategory === \"ANCHOR\") {\n          matchSec = s.isFrontPage && s.category !== \"IPO\" && s.category !== \"Corporate Events\" && s.category !== \"Corporate Appointments\" && !s.isOpinion;\n        } else if (selectedFeedCategory === \"IPO_ALL\") {\n          matchSec = s.category === \"IPO\";\n        } else if (selectedFeedCategory === \"IPO_DRHP\") {\n          matchSec = s.category === \"IPO\" && (s.ipoTag === \"DRHP\" || !s.ipoTag);\n        } else if (selectedFeedCategory === \"IPO_BIDDING\") {\n          matchSec = s.category === \"IPO\" && s.ipoTag === \"BIDDING\";\n        } else if (selectedFeedCategory === \"IPO_NOTICES\") {\n          matchSec = s.category === \"IPO\" && s.ipoTag === \"NOTICES\";\n        } else if (selectedFeedCategory === \"CORPORATE_ALL\") {\n          matchSec = s.category === \"Corporate Events\" || s.category === \"Corporate Appointments\";\n        } else if (selectedFeedCategory === \"EVENTS\") {\n          matchSec = s.category === \"Corporate Events\";\n        } else if (selectedFeedCategory === \"APPOINTMENTS\") {\n          matchSec = s.category === \"Corporate Appointments\";\n        } else if (selectedFeedCategory === \"OPINIONS\") {\n          matchSec = s.isOpinion;\n        } else if (selectedFeedCategory === \"Others\") {\n          matchSec = s.category === \"Others\" && !s.isOpinion;\n        } else {\n          matchSec = s.category === selectedFeedCategory && !s.isOpinion;\n        }\n\n        const matchSent = selectedFeedSentiment === \"ALL\" || s.sentiment === selectedFeedSentiment;\n        const matchStock = !activeStockFilter || (s.stocks && s.stocks.includes(activeStockFilter));\n        const matchSector = !activeSectorFilter || (s.sectors && s.sectors.includes(activeSectorFilter)) || (s.category && s.category.toUpperCase().includes(activeSectorFilter));\n\n        return matchSec && matchSent && matchStock && matchSector && matchQuery;\n      });\n    }\n\n    function navigateStory(dir) {\n      const displayed = getFilteredStories();\n      const total = displayed.length;\n      if (total === 0) return;\n      selectedStoryIndex += dir;\n      if (selectedStoryIndex < 0) selectedStoryIndex = 0;\n      if (selectedStoryIndex >= total) selectedStoryIndex = total - 1;\n      currentFeedPage = Math.floor(selectedStoryIndex / FEED_PAGE_SIZE) + 1;\n      renderFeedList();\n    }\n\n    function changeFeedPage(delta) {\n      const displayed = getFilteredStories();\n      const totalPages = Math.ceil(displayed.length / FEED_PAGE_SIZE) || 1;\n      const targetPage = currentFeedPage + delta;\n      if (targetPage >= 1 && targetPage <= totalPages) {\n        currentFeedPage = targetPage;\n        selectedStoryIndex = (currentFeedPage - 1) * FEED_PAGE_SIZE;\n        renderFeedList();\n      }\n    }\n\n    // ================= SEARCH HANDLING =================\n    function onSearchInput() {\n      const val = document.getElementById(\"global-search\").value.trim();\n      currentSearchQuery = val;\n      selectedStoryIndex = 0;\n      currentFeedPage = 1;\n      document.getElementById(\"clear-search-btn\").classList.toggle(\"hidden\", val.length === 0);\n      \n      if (currentView === \"ipo\") {\n        renderIpoTable();\n      } else if (currentLayoutMode === \"split\") {\n        renderFeedList();\n      } else {\n        renderMatrixTable();\n      }\n    }\n\n    function clearSearch() {\n      document.getElementById(\"global-search\").value = \"\";\n      currentSearchQuery = \"\";\n      selectedStoryIndex = 0;\n      currentFeedPage = 1;\n      document.getElementById(\"clear-search-btn\").classList.add(\"hidden\");\n      if (currentView === \"ipo\") renderIpoTable();\n      else if (currentLayoutMode === \"split\") renderFeedList();\n      else renderMatrixTable();\n    }\n\n    // ================= ACCORDION SIDEBAR (MATCHING ATTACHED IMAGE 2) =================\n    let treeState = {\n      categories: true,  // Open by default\n      desks: true,\n      sectors: false,    // Collapsed by default\n      stocks: false      // Collapsed by default\n    };\n\n    let sidebarSearchTerm = \"\";\n\n    function onSidebarFilterInput(val) {\n      sidebarSearchTerm = val.trim().toLowerCase();\n      renderCategoriesAndStocksSidebar();\n    }\n\n    function toggleTreeNode(section) {\n      treeState[section] = !treeState[section];\n      renderCategoriesAndStocksSidebar();\n    }\n\n    function toggleAllTreeSections() {\n      const allOpen = treeState.categories && treeState.desks && treeState.sectors && treeState.stocks;\n      const nextState = !allOpen;\n      treeState.categories = nextState;\n      treeState.desks = nextState;\n      treeState.sectors = nextState;\n      treeState.stocks = nextState;\n      renderCategoriesAndStocksSidebar();\n    }\n\n    function renderCategoriesAndStocksSidebar() {\n      const container = document.getElementById(\"sidebar-accordion-container\");\n      if (!container) return;\n\n      container.innerHTML = \"\";\n\n      const coreStories = stories.filter(s => s.category !== \"IPO\" && s.category !== \"Corporate Events\" && s.category !== \"Corporate Appointments\" && !s.isOpinion);\n      const totalIpos = ipoList.length;\n      const anchorCount = coreStories.filter(s => s.isFrontPage).length;\n      const corpEventsCount = stories.filter(s => s.category === \"Corporate Events\").length;\n      const corpApptsCount = stories.filter(s => s.category === \"Corporate Appointments\").length;\n      const corpCount = corpEventsCount + corpApptsCount;\n      const opinionsCount = stories.filter(s => s.isOpinion).length;\n\n      // Group 1: Core News Desks\n      const coreNewsItems = [\n        { id: \"ALL\", label: \"All News\", count: coreStories.length },\n        { id: \"ANCHOR\", label: \"Front Page\", count: anchorCount },\n        { id: \"Sector\", label: \"Sector News\", count: stories.filter(s => s.category === \"Sector\" && !s.isOpinion).length },\n        { id: \"Economy\", label: \"Economy\", count: stories.filter(s => s.category === \"Economy\" && !s.isOpinion).length },\n        { id: \"Policy\", label: \"Policy & Regulations\", count: stories.filter(s => s.category === \"Policy\" && !s.isOpinion).length },\n        { id: \"Market\", label: \"Market Pulse\", count: stories.filter(s => s.category === \"Market\" && !s.isOpinion).length },\n        { id: \"Trade\", label: \"Trade & FX\", count: stories.filter(s => s.category === \"Trade\" && !s.isOpinion).length },\n        { id: \"International News\", label: \"International\", count: stories.filter(s => s.category === \"International News\" && !s.isOpinion).length },\n        { id: \"Others\", label: \"General Features\", count: stories.filter(s => s.category === \"Others\" && !s.isOpinion).length }\n      ];\n\n      // Group 2: Specialized Desks\n      const deskItems = [\n        { id: \"IPO_ALL\", label: \"IPO Central\", count: totalIpos },\n        { id: \"CORPORATE_ALL\", label: \"Corporate Desk\", count: corpCount },\n        { id: \"EVENTS\", label: \"Corp Events\", count: corpEventsCount },\n        { id: \"APPOINTMENTS\", label: \"Appointments\", count: corpApptsCount },\n        { id: \"OPINIONS\", label: \"Opinions Desk\", count: opinionsCount }\n      ];\n\n      // Group 3: Industry Sectors\n      const secCounts = {};\n      stories.forEach(s => {\n        (s.sectors || []).forEach(sec => secCounts[sec] = (secCounts[sec] || 0) + 1);\n      });\n      const sortedSecs = Object.keys(secCounts).sort((a,b) => secCounts[b] - secCounts[a]);\n\n      // Group 4: Company Stocks\n      const stockCounts = {};\n      stories.forEach(s => {\n        (s.stocks || []).forEach(stk => stockCounts[stk] = (stockCounts[stk] || 0) + 1);\n      });\n      const sortedStocks = Object.keys(stockCounts).sort((a,b) => stockCounts[b] - stockCounts[a]);\n\n      const statEl = document.getElementById(\"sidebar-total-stat\");\n      if (statEl) statEl.textContent = `${coreNewsItems.length + deskItems.length} \u00b7 ${sortedStocks.length}`;\n\n      const expandText = document.getElementById(\"expand-all-text\");\n      const allOpen = treeState.categories && treeState.desks && treeState.sectors && treeState.stocks;\n      if (expandText) expandText.textContent = allOpen ? \"Collapse all\" : \"Expand all\";\n\n      const filterIndicator = document.getElementById(\"active-filter-indicator\");\n      if (filterIndicator) {\n        if (activeStockFilter || activeSectorFilter || selectedFeedCategory !== 'ALL') {\n          filterIndicator.innerHTML = `<button onclick=\"clearAllStockAndSectorFilters(); onCategorySelect('ALL');\" class=\"hover:underline font-bold text-amber-700 dark:text-amber-400\">Clear filters (\u2715)</button>`;\n        } else {\n          filterIndicator.textContent = \"\";\n        }\n      }\n\n      // Helper to build Accordion Group row matching Image 2\n      function createAccordionGroup(title, count, isExpanded, onToggle, items, renderItemFn) {\n        const groupWrapper = document.createElement(\"div\");\n        groupWrapper.className = \"flex flex-col\";\n\n        const isGroupActive = items.some(it => it.isSelected);\n\n        const headerBtn = document.createElement(\"button\");\n        headerBtn.className = `w-full text-left px-3 py-2.5 flex items-center justify-between transition-colors select-none ${\n          isGroupActive \n            ? 'border-l-4 border-indigo-600 bg-slate-100/90 dark:bg-slate-800/80 font-bold text-slate-900 dark:text-white' \n            : 'border-l-4 border-transparent hover:bg-slate-50 dark:hover:bg-slate-800/40 text-slate-800 dark:text-slate-200 font-medium'\n        }`;\n        headerBtn.onclick = onToggle;\n        headerBtn.innerHTML = `\n          <div class=\"flex items-center gap-2\">\n            <span class=\"text-[10px] text-slate-500 dark:text-slate-400 transition-transform ${isExpanded ? 'rotate-90' : ''}\">\u25b6</span>\n            <span class=\"text-[13px] font-sans font-medium\">${title}</span>\n            <span class=\"text-[11.5px] font-normal text-slate-400 dark:text-slate-500 font-sans\">(${count})</span>\n          </div>\n        `;\n        groupWrapper.appendChild(headerBtn);\n\n        if (isExpanded) {\n          const bodyDiv = document.createElement(\"div\");\n          bodyDiv.className = \"pl-6 pr-2 py-1 flex flex-col gap-0.5 bg-slate-50/40 dark:bg-slate-900/30 border-t border-slate-100/80 dark:border-slate-800/50\";\n          items.forEach(it => {\n            const itemRow = renderItemFn(it);\n            if (itemRow) bodyDiv.appendChild(itemRow);\n          });\n          groupWrapper.appendChild(bodyDiv);\n        }\n\n        return groupWrapper;\n      }\n\n      // 1. Core Categories Section\n      const filteredCore = coreNewsItems.filter(it => !sidebarSearchTerm || it.label.toLowerCase().includes(sidebarSearchTerm));\n      if (filteredCore.length > 0) {\n        const coreGroup = createAccordionGroup(\n          \"News Categories\",\n          coreNewsItems.length,\n          treeState.categories || !!sidebarSearchTerm,\n          () => toggleTreeNode('categories'),\n          filteredCore.map(it => ({ ...it, isSelected: selectedFeedCategory === it.id })),\n          (it) => {\n            const btn = document.createElement(\"button\");\n            btn.className = `w-full text-left px-2 py-1 rounded text-[12px] font-sans flex items-center justify-between transition-colors ${\n              it.isSelected ? 'bg-indigo-600 text-white font-bold shadow-xs' : 'text-slate-700 dark:text-slate-300 hover:bg-slate-200/60 dark:hover:bg-slate-800 font-medium'\n            }`;\n            btn.innerHTML = `\n              <span class=\"truncate\">${it.label}</span>\n              <span class=\"text-[11px] opacity-75 font-mono\">(${it.count})</span>\n            `;\n            btn.onclick = () => {\n              if (it.id === 'ANCHOR') switchView('anchor');\n              else onCategorySelect(it.isSelected ? 'ALL' : it.id);\n            };\n            return btn;\n          }\n        );\n        container.appendChild(coreGroup);\n      }\n\n      // 2. Specialized Desks Section\n      const filteredDesks = deskItems.filter(it => !sidebarSearchTerm || it.label.toLowerCase().includes(sidebarSearchTerm));\n      if (filteredDesks.length > 0) {\n        const deskGroup = createAccordionGroup(\n          \"Specialized Desks\",\n          deskItems.length,\n          treeState.desks || !!sidebarSearchTerm,\n          () => toggleTreeNode('desks'),\n          filteredDesks.map(it => ({ ...it, isSelected: selectedFeedCategory === it.id || (it.id === 'IPO_ALL' && currentView === 'ipo') || (it.id === 'CORPORATE_ALL' && currentView === 'corporate') })),\n          (it) => {\n            const btn = document.createElement(\"button\");\n            btn.className = `w-full text-left px-2 py-1 rounded text-[12px] font-sans flex items-center justify-between transition-colors ${\n              it.isSelected ? 'bg-amber-700 text-white font-bold shadow-xs' : 'text-slate-700 dark:text-slate-300 hover:bg-amber-100/60 dark:hover:bg-amber-950/40 font-medium'\n            }`;\n            btn.innerHTML = `\n              <span class=\"truncate\">${it.label}</span>\n              <span class=\"text-[11px] opacity-75 font-mono\">(${it.count})</span>\n            `;\n            btn.onclick = () => {\n              if (it.id === 'IPO_ALL') onDeskSelect('ipo');\n              else if (it.id === 'CORPORATE_ALL') onDeskSelect('corporate');\n              else if (it.id === 'EVENTS') selectCorporateSub('EVENTS');\n              else if (it.id === 'APPOINTMENTS') selectCorporateSub('APPOINTMENTS');\n              else if (it.id === 'OPINIONS') onDeskSelect('opinions');\n            };\n            return btn;\n          }\n        );\n        container.appendChild(deskGroup);\n      }\n\n      // 3. Industry Sectors Section\n      const filteredSectors = sortedSecs.filter(sec => !sidebarSearchTerm || sec.toLowerCase().includes(sidebarSearchTerm));\n      if (filteredSectors.length > 0) {\n        const secGroup = createAccordionGroup(\n          \"Industry Sectors\",\n          sortedSecs.length,\n          treeState.sectors || !!sidebarSearchTerm,\n          () => toggleTreeNode('sectors'),\n          filteredSectors.map(sec => ({ id: sec, label: sec, count: secCounts[sec], isSelected: activeSectorFilter === sec })),\n          (it) => {\n            const btn = document.createElement(\"button\");\n            btn.className = `w-full text-left px-2 py-1 rounded text-[12px] font-sans flex items-center justify-between transition-colors ${\n              it.isSelected ? 'bg-indigo-600 text-white font-bold shadow-xs' : 'text-slate-700 dark:text-slate-300 hover:bg-indigo-100/60 dark:hover:bg-indigo-950/40 font-medium'\n            }`;\n            btn.innerHTML = `\n              <span class=\"truncate\">${it.label}</span>\n              <span class=\"text-[11px] opacity-75 font-mono\">(${it.count})</span>\n            `;\n            btn.onclick = () => {\n              activeSectorFilter = activeSectorFilter === it.id ? null : it.id;\n              selectedStoryIndex = 0;\n              currentFeedPage = 1;\n              renderCategoriesAndStocksSidebar();\n              if (currentLayoutMode === \"split\") renderFeedList();\n              else renderMatrixTable();\n            };\n            return btn;\n          }\n        );\n        container.appendChild(secGroup);\n      }\n\n      // 4. Company Stocks Section\n      const filteredStocks = sortedStocks.filter(stk => !sidebarSearchTerm || stk.toLowerCase().includes(sidebarSearchTerm));\n      if (filteredStocks.length > 0) {\n        const stockGroup = createAccordionGroup(\n          \"Company Stocks\",\n          sortedStocks.length,\n          treeState.stocks || !!sidebarSearchTerm,\n          () => toggleTreeNode('stocks'),\n          filteredStocks.map(stk => ({ id: stk, label: stk, count: stockCounts[stk], isSelected: activeStockFilter === stk })),\n          (it) => {\n            const btn = document.createElement(\"button\");\n            btn.className = `w-full text-left px-2 py-1 rounded text-[12px] font-sans flex items-center justify-between transition-colors ${\n              it.isSelected ? 'bg-amber-600 text-white font-bold shadow-xs' : 'text-slate-700 dark:text-slate-300 hover:bg-amber-100/60 dark:hover:bg-amber-950/40 font-medium'\n            }`;\n            btn.innerHTML = `\n              <span class=\"truncate\">${it.label}</span>\n              <span class=\"text-[11px] opacity-75 font-mono\">(${it.count})</span>\n            `;\n            btn.onclick = () => {\n              activeStockFilter = activeStockFilter === it.id ? null : it.id;\n              selectedStoryIndex = 0;\n              currentFeedPage = 1;\n              renderCategoriesAndStocksSidebar();\n              if (currentLayoutMode === \"split\") renderFeedList();\n              else renderMatrixTable();\n            };\n            return btn;\n          }\n        );\n        container.appendChild(stockGroup);\n      }\n    }\n\n    function clearAllStockAndSectorFilters() {\n      activeStockFilter = null;\n      activeSectorFilter = null;\n      selectedStoryIndex = 0;\n      currentFeedPage = 1;\n      renderCategoriesAndStocksSidebar();\n      if (currentLayoutMode === \"split\") renderFeedList();\n      else renderMatrixTable();\n    }\n\n    function clearStockFilter() {\n      clearAllStockAndSectorFilters();\n    }\n\n    function setFeedSentiment(sent) {\n      selectedFeedSentiment = sent;\n      selectedStoryIndex = 0;\n      currentFeedPage = 1;\n      const allBtn = document.getElementById(\"sent-all\");\n      const bullBtn = document.getElementById(\"sent-bullish\");\n      const bearBtn = document.getElementById(\"sent-bearish\");\n      \n      if (allBtn) allBtn.className = sent === \"ALL\" \n        ? \"px-2.5 py-0.5 rounded-md bg-[#1C1917] text-white dark:bg-slate-700 shadow-xs font-semibold\" \n        : \"px-2.5 py-0.5 rounded-md text-slate-800 dark:text-slate-300 hover:bg-white/60 dark:hover:bg-slate-800 font-medium\";\n        \n      if (bullBtn) bullBtn.className = sent === \"BULLISH\" \n        ? \"px-2.5 py-0.5 rounded-md bg-emerald-700 text-white shadow-xs font-semibold flex items-center gap-0.5\" \n        : \"px-2.5 py-0.5 rounded-md text-emerald-900 dark:text-emerald-400 hover:bg-emerald-100/60 dark:hover:bg-emerald-950/40 flex items-center gap-0.5 font-medium\";\n        \n      if (bearBtn) bearBtn.className = sent === \"BEARISH\" \n        ? \"px-2.5 py-0.5 rounded-md bg-rose-700 text-white shadow-xs font-semibold flex items-center gap-0.5\" \n        : \"px-2.5 py-0.5 rounded-md text-rose-900 dark:text-rose-400 hover:bg-rose-100/60 dark:hover:bg-rose-950/40 flex items-center gap-0.5 font-medium\";\n\n      renderFeedList();\n    }\n\n    // ================= FEED LIST & ACTIVE STORY DETAIL (MAX 12 1-LINER STORIES PER PAGE) =================\n    function renderFeedList() {\n      const rawQuery = document.getElementById(\"global-search\").value.trim().toLowerCase();\n      const queryTokens = rawQuery ? rawQuery.split(/\\s+/).filter(Boolean) : [];\n      \n      const displayed = getFilteredStories();\n      const totalStories = displayed.length;\n      const totalPages = Math.ceil(totalStories / FEED_PAGE_SIZE) || 1;\n\n      if (currentFeedPage > totalPages) currentFeedPage = totalPages;\n      if (currentFeedPage < 1) currentFeedPage = 1;\n\n      const startIndex = (currentFeedPage - 1) * FEED_PAGE_SIZE;\n      const endIndex = Math.min(startIndex + FEED_PAGE_SIZE, totalStories);\n      const pageStories = displayed.slice(startIndex, endIndex);\n\n      // Header indicator\n      const countBadge = document.getElementById(\"feed-list-count\");\n      if (countBadge) {\n        countBadge.textContent = totalStories > 0 ? `${startIndex + 1}-${endIndex} of ${totalStories}` : `0 Stories`;\n      }\n\n      // Pagination Controls\n      const pagInfo = document.getElementById(\"feed-pagination-info\");\n      if (pagInfo) {\n        pagInfo.textContent = `Page ${currentFeedPage} / ${totalPages} (${totalStories})`;\n      }\n      const prevBtn = document.getElementById(\"feed-prev-page\");\n      const nextBtn = document.getElementById(\"feed-next-page\");\n      if (prevBtn) {\n        prevBtn.disabled = currentFeedPage <= 1;\n        prevBtn.className = currentFeedPage <= 1 \n          ? \"px-2 py-0.5 rounded bg-slate-100 dark:bg-slate-800 text-[10.5px] font-medium text-slate-400 dark:text-slate-600 border border-slate-200 dark:border-slate-800 cursor-not-allowed opacity-50\"\n          : \"px-2 py-0.5 rounded bg-white dark:bg-slate-800 hover:bg-amber-50 text-[10.5px] font-semibold text-slate-900 dark:text-slate-200 border border-slate-300 dark:border-slate-700 shadow-2xs cursor-pointer\";\n      }\n      if (nextBtn) {\n        nextBtn.disabled = currentFeedPage >= totalPages;\n        nextBtn.className = currentFeedPage >= totalPages \n          ? \"px-2 py-0.5 rounded bg-slate-100 dark:bg-slate-800 text-[10.5px] font-medium text-slate-400 dark:text-slate-600 border border-slate-200 dark:border-slate-800 cursor-not-allowed opacity-50\"\n          : \"px-2 py-0.5 rounded bg-white dark:bg-slate-800 hover:bg-amber-50 text-[10.5px] font-semibold text-slate-900 dark:text-slate-200 border border-slate-300 dark:border-slate-700 shadow-2xs cursor-pointer\";\n      }\n\n      const listContainer = document.getElementById(\"feed-list-container\");\n      listContainer.innerHTML = \"\";\n\n      if (totalStories === 0) {\n        listContainer.innerHTML = `\n          <div class=\"p-8 text-center text-slate-400\">\n            <p class=\"text-base font-semibold text-slate-700 dark:text-slate-300\">No news stories found</p>\n            <p class=\"text-[12.5px] mt-1 text-slate-500\">Try broadening your search term or selecting another section.</p>\n            ${rawQuery ? `<button onclick=\"clearSearch()\" class=\"mt-3 px-3 py-1 bg-amber-700 text-white rounded-md text-xs font-semibold\">Clear Search</button>` : ''}\n          </div>\n        `;\n        document.getElementById(\"feed-detail-container\").innerHTML = `<div class=\"p-8 text-center text-slate-400 text-[13.5px]\">Select a story to view analysis.</div>`;\n        return;\n      }\n\n      if (selectedStoryIndex < startIndex || selectedStoryIndex >= endIndex) {\n        selectedStoryIndex = startIndex;\n      }\n\n      pageStories.forEach((s, localIdx) => {\n        const globalIdx = startIndex + localIdx;\n        const isSelected = globalIdx === selectedStoryIndex;\n        const numStr = (globalIdx + 1).toString().padStart(2, '0');\n        const dot = s.sentiment === \"BULLISH\" ? \"bg-emerald-500\" : s.sentiment === \"BEARISH\" ? \"bg-rose-500\" : \"bg-slate-400\";\n\n        const activeStyle = \"bg-[#FAF5FF] dark:bg-[#1E1B4B]/70 border-2 border-[#8B5CF6] dark:border-[#A78BFA] shadow-xs text-[#6B21A8] dark:text-[#E9D5FF]\";\n        const inactiveStyle = \"bg-white dark:bg-[#0D1322] border border-slate-200 dark:border-slate-800 hover:border-purple-300 dark:hover:border-purple-900/60 hover:bg-[#FAF5FF]/50 dark:hover:bg-slate-800/50 text-slate-900 dark:text-slate-100\";\n\n        const btn = document.createElement(\"button\");\n        btn.className = `w-full text-left px-3.5 py-2.5 rounded-lg transition-all flex items-center gap-2.5 mb-2 last:mb-0 cursor-pointer ${isSelected ? activeStyle : inactiveStyle}`;\n        btn.onclick = () => {\n          selectedStoryIndex = globalIdx;\n          renderFeedList();\n          // On mobile screens (iPhone / tablet), smoothly scroll reader panel into view\n          if (window.innerWidth < 1024) {\n            const detailWrapper = document.getElementById(\"feed-detail-wrapper\");\n            if (detailWrapper) {\n              detailWrapper.scrollIntoView({ behavior: 'smooth', block: 'start' });\n            }\n          }\n        };\n\n        btn.innerHTML = `\n          <span class=\"shrink-0 text-[11px] font-mono font-bold ${isSelected ? 'text-[#8B5CF6] dark:text-[#C4B5FD]' : 'text-slate-400'} tabular-nums w-4\">${numStr}</span>\n          <span class=\"w-2 h-2 rounded-full shrink-0 ${dot}\"></span>\n          <h4 class=\"text-[13.5px] font-sans font-medium ${isSelected ? 'text-[#581C87] dark:text-[#E9D5FF]' : 'text-[#090D16] dark:text-[#F8FAFC]'} tracking-tight truncate flex-1 min-w-0\"  title=\"${escapeQuotes(s.headline)}\">\n            ${highlightSearchTokens(s.headline, queryTokens)}\n          </h4>\n        `;\n        listContainer.appendChild(btn);\n      });\n\n      renderActiveStoryDetail(displayed[selectedStoryIndex], queryTokens);\n    }\n\n    function formatPageSource(pageStr) {\n      if (!pageStr) return \"\ud83d\udcf0 FE / BS\";\n      const p = pageStr.trim();\n      if (p.startsWith(\"FE\") || p.startsWith(\"BS\") || p.includes(\"FE (\") || p.includes(\"BS (\") || p.includes(\"FE / BS\") || p.includes(\"FE:\") || p.includes(\"BS:\")) {\n        return `\ud83d\udcf0 ${p}`;\n      }\n      return `\ud83d\udcf0 ${p}`;\n    }\n\n    function renderActiveStoryDetail(story, queryTokens = []) {\n      const container = document.getElementById(\"feed-detail-container\");\n      if (!story) return;\n\n      const isBullish = story.sentiment === \"BULLISH\";\n      const isBearish = story.sentiment === \"BEARISH\";\n      \n      const sentBadge = isBullish \n        ? `<span class=\"px-2.5 py-0.5 rounded text-[11px] font-mono font-bold bg-emerald-100 text-emerald-950 border border-emerald-300 dark:bg-emerald-950/70 dark:text-emerald-200\">\ud83d\udfe2 BULLISH</span>`\n        : isBearish \n        ? `<span class=\"px-2.5 py-0.5 rounded text-[11px] font-mono font-bold bg-rose-100 text-rose-950 border border-rose-300 dark:bg-rose-950/70 dark:text-rose-200\">\ud83d\udd34 BEARISH</span>`\n        : `<span class=\"px-2.5 py-0.5 rounded text-[11px] font-mono font-bold bg-slate-200 text-slate-900 border border-slate-300 dark:bg-slate-800 dark:text-slate-200\">\u26aa NEUTRAL</span>`;\n\n      const tickerBadges = story.tickers.map(t => `<span class=\"px-2.5 py-0.5 text-[11.5px] font-mono font-bold rounded-md bg-indigo-50 text-indigo-900 border border-indigo-200 dark:bg-indigo-950/60 dark:text-indigo-200\">${t}</span>`).join('');\n\n      // Break brief details into short punchy sentences (NO paragraph walls)\n      const briefSentences = (story.brief_details || \"\").split(/(?<=[.?!])\\s+/).filter(Boolean);\n\n      container.innerHTML = `\n        <!-- Mobile Fast Navigation Bar -->\n        <div class=\"lg:hidden flex items-center justify-between pb-1.5 mb-1.5 border-b border-slate-200 dark:border-slate-800\">\n          <button onclick=\"window.scrollTo({ top: 0, behavior: 'smooth' })\" class=\"text-[12px] font-mono font-bold text-indigo-600 dark:text-indigo-400 flex items-center gap-1 py-1 px-2 rounded bg-indigo-50 dark:bg-indigo-950/50\">\n            <span>\u25b2 Back to Headlines</span>\n          </button>\n          <span class=\"text-[11px] font-mono text-slate-400\">Story #${story.id}</span>\n        </div>\n\n        <div class=\"flex items-center justify-between gap-2 flex-wrap pb-2 border-b border-slate-200 dark:border-slate-800\">\n          <div class=\"flex items-center gap-1.5 flex-wrap\">\n            <span class=\"text-[11.5px] font-mono font-semibold px-2.5 py-0.5 rounded bg-slate-200 text-slate-900 dark:bg-slate-800 dark:text-white\">${story.category}</span>\n            ${story.isFrontPage ? `<span class=\"text-[10.5px] font-mono font-semibold px-2 py-0.5 rounded bg-amber-200 text-amber-950 dark:bg-amber-950/80 dark:text-amber-200\">\ud83d\udcf0 PAGE 1 ANCHOR</span>` : ''}\n            <span class=\"text-[11.5px] font-mono font-semibold px-2 py-0.5 rounded bg-slate-100 dark:bg-slate-800/80 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700\">${formatPageSource(story.page_numbers)}</span>\n          </div>\n          <div class=\"flex items-center gap-1.5\">\n            <button id=\"feed-open-sidebar-btn\" onclick=\"toggleSidebar()\" class=\"hidden text-[11.5px] font-mono font-bold px-2.5 py-0.5 rounded border border-[#DFC0A5] dark:border-slate-700 bg-[#FBE8D8] dark:bg-[#1E1B4B] text-[#1C1917] dark:text-[#E0E7FF] hover:bg-[#F3DECC] shadow-2xs items-center gap-1.5 cursor-pointer transition-all\" title=\"Open 3rd Column Filters & Desks\"><span>\u2630</span> <span>Filters</span></button>\n            ${sentBadge}\n            <button onclick=\"copyToClipboard('${escapeQuotes(story.headline + '\\\\n\\\\n' + story.brief_details)}')\" class=\"text-[11.5px] text-slate-800 hover:text-slate-950 dark:text-slate-200 dark:hover:text-white font-mono flex items-center gap-1 font-semibold px-2.5 py-0.5 rounded border border-slate-300 dark:border-slate-700 bg-white dark:bg-[#141A2E] shadow-2xs\" title=\"Copy story summary\">\n              \ud83d\udccb Copy\n            </button>\n          </div>\n        </div>\n\n        <h1 class=\"text-[20px] sm:text-[22px] font-bold text-[#05080F] dark:text-white leading-snug tracking-tight mt-1 mb-2 flex items-center flex-wrap gap-2\">\n          <span>${highlightSearchTokens(highlightNumbers(story.headline), queryTokens)}</span>\n          ${story.tickers.length > 0 ? tickerBadges : ''}\n        </h1>\n\n        <!-- 2-COLUMN SIDE-BY-SIDE GRID: LEFT (GIST + CATALYST) & RIGHT (KEY ANALYST DATA POINTS) -->\n        <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-3.5 items-start mt-2.5\">\n          \n          <!-- LEFT COLUMN (lg:col-span-6): CORE TRADER TAKEAWAY + CATALYST DIRECTLY BELOW -->\n          <div class=\"lg:col-span-6 flex flex-col gap-3\">\n            \n            <!-- \u26a1 SECTION 1: EXECUTIVE GIST (MATCHING ATTACHED IMAGE FONT & LINE SPACING) -->\n            <div class=\"rounded-xl border-2 border-indigo-300 dark:border-indigo-800 bg-indigo-50/60 dark:bg-[#13182E] p-3.5 shadow-xs flex flex-col gap-2.5\">\n              <div class=\"flex items-center justify-between border-b border-indigo-200/90 dark:border-indigo-900/60 pb-1.5\">\n                <span class=\"text-[12px] font-mono font-extrabold uppercase tracking-wider text-indigo-950 dark:text-indigo-200 flex items-center gap-1.5\">\n                  <span>\u26a1</span> <span>1. Executive Gist</span>\n                </span>\n                <span class=\"text-[10.5px] font-mono font-bold px-2 py-0.5 rounded bg-indigo-200/80 text-indigo-950 dark:bg-indigo-900/80 dark:text-indigo-200\">Key Takeaway</span>\n              </div>\n              <div class=\"space-y-2.5\">\n                ${briefSentences.map(sent => `\n                  <div class=\"flex items-start gap-2.5 bg-white/95 dark:bg-[#0E1322] p-3 rounded-lg border border-indigo-100 dark:border-slate-800 text-[14.5px] sm:text-[15px] text-[#090D16] dark:text-[#F8FAFC] leading-[1.6] font-normal shadow-2xs font-sans tracking-tight\">\n                    <span class=\"text-indigo-600 dark:text-indigo-400 font-bold select-none mt-0.5\">\u25b8</span>\n                    <span class=\"leading-[1.6]\">${highlightSearchTokens(highlightNumbers(sent), queryTokens)}</span>\n                  </div>\n                `).join('')}\n              </div>\n            </div>\n\n            <!-- \ud83d\udca1 SECTION 2: TRADER CATALYST & IMPACT ANALYSIS (PLACED DIRECTLY BELOW EXECUTIVE GIST!) -->\n            <div class=\"p-3.5 rounded-xl border-2 ${isBullish ? 'border-emerald-500 bg-emerald-50/70 dark:bg-[#064E3B]/30 dark:border-emerald-600' : isBearish ? 'border-rose-500 bg-rose-50/70 dark:bg-[#881337]/30 dark:border-rose-600' : 'border-slate-400 bg-slate-50 dark:bg-slate-900/50 dark:border-slate-700'} shadow-xs flex flex-col gap-2.5\">\n              <div class=\"flex items-center justify-between border-b ${isBullish ? 'border-emerald-200 dark:border-emerald-900/60' : isBearish ? 'border-rose-200 dark:border-rose-900/60' : 'border-slate-200 dark:border-slate-800'} pb-1.5\">\n                <span class=\"text-[12px] font-mono font-extrabold uppercase tracking-wider ${isBullish ? 'text-emerald-950 dark:text-emerald-300' : isBearish ? 'text-rose-950 dark:text-rose-300' : 'text-slate-900 dark:text-slate-200'} flex items-center gap-1.5\">\n                  <span>\ud83d\udca1</span> <span>2. Catalyst & Market Impact</span>\n                </span>\n                <span class=\"text-[10.5px] font-mono font-extrabold uppercase px-2 py-0.5 rounded ${isBullish ? 'bg-emerald-200 text-emerald-950 dark:bg-emerald-900 dark:text-emerald-200' : isBearish ? 'bg-rose-200 text-rose-950 dark:bg-rose-900 dark:text-rose-200' : 'bg-slate-200 text-slate-900 dark:bg-slate-800 dark:text-slate-200'}\">${story.sentiment} THESIS</span>\n              </div>\n              <div class=\"bg-white/95 dark:bg-[#0E1322] p-3 rounded-lg border ${isBullish ? 'border-emerald-200/60 dark:border-slate-800' : isBearish ? 'border-rose-200/60 dark:border-slate-800' : 'border-slate-200 dark:border-slate-800'} text-[14.5px] sm:text-[15px] text-[#090D16] dark:text-[#F8FAFC] leading-[1.6] font-normal shadow-2xs font-sans tracking-tight\">\n                ${highlightSearchTokens(highlightNumbers(story.sentimentReasoning), queryTokens)}\n              </div>\n            </div>\n\n          </div>\n\n          <!-- RIGHT COLUMN (lg:col-span-6): KEY ANALYST DATA POINTS -->\n          <div class=\"lg:col-span-6 flex flex-col gap-2\">\n            \n            <!-- \ud83d\udccc SECTION 3: KEY ANALYST DATA POINTS (WITH EXACT IMAGE FONT & SPACING) -->\n            <div class=\"rounded-xl border-2 border-[#C9B7A5] dark:border-[#524434] bg-[#FDFBF7] dark:bg-[#191512] p-3.5 shadow-xs flex flex-col gap-2.5\">\n              <div class=\"flex items-center justify-between border-b border-[#E8DCCE] dark:border-[#382E25] pb-1.5\">\n                <span class=\"text-[12px] font-mono font-extrabold uppercase tracking-wider text-[#2E1F14] dark:text-[#F3ECE4] flex items-center gap-1.5\">\n                  <span>\ud83d\udccc</span> <span>3. Key Analyst Data Points</span>\n                </span>\n                <span class=\"text-[10.5px] font-mono font-bold px-2 py-0.5 rounded bg-[#EFE5D9] text-[#291B10] dark:bg-[#32261C] dark:text-[#E8DCCF] border border-[#CCAFA0]/50\">Metrics & Facts</span>\n              </div>\n              <ul class=\"space-y-2.5\">\n                ${(story.bullet_points || []).map(bp => `\n                  <li class=\"flex items-start gap-2.5 text-[14.5px] sm:text-[15px] text-[#090D16] dark:text-[#F8FAFC] leading-[1.6] bg-white/95 dark:bg-[#0E1322] p-3 rounded-lg border border-[#EBE2D8] dark:border-slate-800 shadow-2xs font-normal font-sans tracking-tight\">\n                    <span class=\"text-[#8C5E3C] dark:text-[#CBB09C] font-bold select-none mt-0.5 text-base\">\u203a</span>\n                    <span class=\"leading-[1.6]\">${highlightSearchTokens(highlightNumbers(bp), queryTokens)}</span>\n                  </li>\n                `).join('')}\n              </ul>\n            </div>\n\n          </div>\n\n        </div>\n      `;\n    }\n\n    function highlightNumbers(text) {\n      if (!text) return \"\";\n      return text.replace(/(\\b\\d+(?:\\.\\d+)?%|\\b\u20b9\\s?[\\d,]+(?:\\.\\d+)?(?:\\s?(?:cr|crore|lakh|bn|billion|tn|trillion))?|\\b\\$[\\d,]+(?:\\.\\d+)?(?:\\s?(?:bn|billion|million|mn|tn))?|\\b[\\d,]+(?:\\.\\d+)?\\s?(?:crore|lakh|billion|million)\\b)/gi, '<span class=\"text-slate-950 dark:text-amber-300 font-semibold font-mono\">$1</span>');\n    }\n\n    function highlightSearchTokens(text, tokens) {\n      if (!text || !tokens || tokens.length === 0) return text;\n      let result = text;\n      tokens.forEach(tok => {\n        if (!tok || tok.length < 2) return;\n        const regex = new RegExp(`(${escapeRegExp(tok)})`, 'gi');\n        result = result.replace(regex, '<mark>$1</mark>');\n      });\n      return result;\n    }\n\n    function escapeRegExp(string) {\n      return string.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\n    }\n\n    function escapeQuotes(str) {\n      return str.replace(/'/g, \"\\\\'\").replace(/\"/g, '&quot;');\n    }\n\n    function copyToClipboard(text) {\n      navigator.clipboard.writeText(text);\n      alert(\"Copied to clipboard!\");\n    }\n\n    document.addEventListener(\"keydown\", (e) => {\n      if (e.target.tagName === \"INPUT\" || e.target.tagName === \"SELECT\" || e.target.tagName === \"TEXTAREA\") return;\n      if (e.key === \"ArrowDown\" || e.key === \"j\") {\n        e.preventDefault();\n        navigateStory(1);\n      } else if (e.key === \"ArrowUp\" || e.key === \"k\") {\n        e.preventDefault();\n        navigateStory(-1);\n      } else if (e.key === \"1\") switchView('feed');\n      else if (e.key === \"2\") switchView('anchor');\n      else if (e.key === \"3\") switchView('ipo');\n      else if (e.key === \"/\") { e.preventDefault(); document.getElementById(\"global-search\").focus(); }\n    });\n\n    initTheme();\n    initFontSize();\n    fetchDates();\n    loadData();\n  </script>\n</body>\n</html>\n";

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    // API proxy to Cloudflare R2 / latest report
    if (url.pathname === '/api/latest' || url.pathname.startsWith('/api/report')) {
      const dateParam = url.searchParams.get('date');
      const targetFile = dateParam ? `news_report_unified_${dateParam}.json` : 'news_report_unified_latest.json';
      const r2Url = `https://pub-c81167dd545d49d0a2cd964a8bd6a1cd.r2.dev/reports/${targetFile}?t=${Date.now()}`;
      try {
        const resp = await fetch(r2Url, {
          headers: { 'User-Agent': 'FinPress-Cloudflare-Worker' },
          cf: { cacheTtl: 0, cacheEverything: false }
        });
        return new Response(resp.body, {
          status: resp.status,
          headers: {
            'Content-Type': 'application/json; charset=utf-8',
            'Access-Control-Allow-Origin': '*',
            'Cache-Control': 'no-cache, no-store, must-revalidate',
            'Pragma': 'no-cache',
            'Expires': '0'
          }
        });
      } catch (e) {
        return new Response(JSON.stringify({ error: 'Failed to fetch report' }), { status: 500 });
      }
    }

    if (url.pathname === '/api/dates') {
      const dates = ['2026-09-29', '2026-09-28', '2026-09-27'];
      return new Response(JSON.stringify(dates), {
        headers: {
          'Content-Type': 'application/json; charset=utf-8',
          'Access-Control-Allow-Origin': '*',
          'Cache-Control': 'no-cache, no-store, must-revalidate'
        }
      });
    }

    // Default: Serve Trader Terminal UI
    return new Response(HTML, {
      headers: {
        'Content-Type': 'text/html; charset=utf-8',
        'Cache-Control': 'no-cache, no-store, must-revalidate'
      }
    });
  }
};
